async function orderOanda(creds, o) {
  const c = requireFields(creds, ['apiKey', 'accountId']);
  const instrument = o.symbol.length === 6 ? `${o.symbol.slice(0, 3)}_${o.symbol.slice(3)}` : o.symbol;
  // OANDA sizes orders in units of the base currency, while this app speaks
  // MT5-style lots (0.01 = micro lot). 1 lot = 100,000 units, so convert.
  const lots = Math.abs(+(o.forexLots || o.quantity || 0.01));
  const unitsNum = Math.max(1, Math.round(lots * 100000));
  const units = o.side === 'SELL' ? -unitsNum : unitsNum;
  const body = {
    order: {
      type: 'MARKET',
      instrument,
      units: String(units),
      timeInForce: 'FOK',
      positionFill: 'DEFAULT'
    }
  };
  const data = await oandaRequest(c, 'POST', `/v3/accounts/${c.accountId}/orders`, body);
  return { orderId: data.orderCreateTransaction?.id || data.orderFillTransaction?.id, ...data };
}

/** Close (part of) an open OANDA position — pct of the units currently held. */
async function closeOanda(creds, o) {
  const c = requireFields(creds, ['apiKey', 'accountId']);
  const instrument = o.symbol.length === 6 ? `${o.symbol.slice(0, 3)}_${o.symbol.slice(3)}` : o.symbol;
  const pct = Math.min(100, Math.max(1, +o.pct || 100));
  let body;
  try {
    const pos = await oandaRequest(c, 'GET', `/v3/accounts/${c.accountId}/positions/${instrument}`);
    const p = pos.position || {};
    const long = +p.long?.units || 0;
    const short = +p.short?.units || 0;
    if (!long && !short) throw new Error(`no open OANDA position for ${instrument}`);
    const take = (units) => String(Math.round(Math.abs(units) * (pct / 100)));
    body = long
      ? { longUnits: pct >= 100 ? 'ALL' : take(long) }
      : { shortUnits: pct >= 100 ? 'ALL' : take(short) };
  } catch (e) {
    if (String(e.message || e).startsWith('no open OANDA')) throw e;
    body = { longUnits: 'ALL', shortUnits: 'ALL' }; // fall back to close everything
  }
  const data = await oandaRequest(c, 'POST', `/v3/accounts/${c.accountId}/positions/${instrument}/close`, body);
  const fill = data.longOrderFillTransaction || data.shortOrderFillTransaction || {};
  return { orderId: fill.id || `oanda-close-${Date.now()}`, price: fill.price, raw: data };
}

