function hasRequiredCreds(platformId, creds) {
  const h = HANDLERS[platformId];
  if (!h) return false;
  if (platformId === 'FOREX_DEMO') return true;
  return h.required.every((f) => creds?.[f] && String(creds[f]).trim());
}

async function testKeys(platformId, creds) {
  const h = HANDLERS[platformId];
  if (!h?.test) throw new Error(`Unsupported platform: ${platformId}`);
  const cleaned = cleanCreds(creds || {});
  // Never mix platforms — only these credentials are used for this id
  const result = await h.test(cleaned);
  return {
    ...result,
    platform: platformId,
    isolated: true,
    usedFields: (h.required || []).filter((f) => !!cleaned[f]),
    note: `Signed only with ${platformId} key/secret stored for this platform`
  };
}

async function placeOrder(platformId, creds, order) {
  const h = HANDLERS[platformId];
  if (!h?.order) {
    throw new Error(`${platformId}: live order connector not available — use DEMO/paper or Binance/Bybit/OKX/KuCoin/Bitget/Gate/MEXC/Kraken/Coinbase/OANDA/MetaTrader 5/MetaTrader 4`);
  }
  return h.order(cleanCreds(creds || {}), order);
}

function supportsLiveOrders(platformId) {
  return Boolean(HANDLERS[platformId]?.order);
}

/**
 * Close (part of) a live position on any platform that can trade live.
 * Crypto spot/futures → opposite market order (reduce-only on futures).
 * OANDA → position close endpoint. MT5 → local bridge close.
 */
async function closePosition(platformId, creds, o) {
  const c = cleanCreds(creds || {});
  if (platformId === 'FOREX_MT5') return closeMt5(c, o);
  if (platformId === 'FOREX_MT4') return closeMt4(c, o);
  if (platformId === 'FOREX_OANDA') return closeOanda(c, o);
  const h = HANDLERS[platformId];
  if (!h?.order) throw new Error(`${platformId}: live close connector not available`);
  const isFutures = o.market === 'FUTURES';
  return h.order(c, {
    market: o.market,
    symbol: o.symbol,
    side: o.side === 'BUY' ? 'SELL' : 'BUY',
    quantity: o.quantity,
    type: 'MARKET',
    reduceOnly: isFutures ? true : undefined,
    marginType: o.marginType,
    leverage: o.leverage,
    forexLots: o.forexLots
  });
}

/* ---------- Pending (unfilled) orders + position check ----------
 * A LIMIT order placed below/above the market is an order on the exchange, not
 * an open position. Only a platform that exposes an open-orders REST API can be
 * read back, so those platforms are the source of truth for “still waiting /
 * filled / cancelled”. Everything else keeps working from the app's own copy. */
const ORDER_LOOKUP_PLATFORMS = new Set(['BINANCE']);

function supportsOrderLookup(platformId) {
  return ORDER_LOOKUP_PLATFORMS.has(platformId);
}

function binanceClient(creds) {
  const c = requireFields(creds, ['apiKey', 'apiSecret']);
  const client = new BinanceClient();
  client.setKeys(c.apiKey, c.apiSecret);
  return client;
}

function normalizeOrder(platformId, market, o) {
  const m = String(market || 'SPOT').toUpperCase();
  return {
    platform: platformId,
    market: m,
    symbol: String(o.symbol || '').toUpperCase(),
    side: o.side,
    type: o.type || (m === 'FUTURES' ? 'LIMIT' : 'LIMIT'),
    price: +o.price || null,
    avgPrice: +o.avgPrice || null,
    qty: +o.origQty || 0,
    filledQty: +o.executedQty || 0,
    status: o.status || 'NEW',
    orderId: String(o.orderId ?? ''),
    at: o.time ? new Date(+o.time).toISOString() : null
  };
}

/** Pending orders waiting on the exchange. null = platform has no such API. */
async function listOpenOrders(platformId, creds, opts = {}) {
  if (!supportsOrderLookup(platformId)) return null;
  const market = String(opts.market || 'SPOT').toUpperCase();
  const client = binanceClient(creds);
  const rows = market === 'FUTURES'
    ? await client.getFuturesOpenOrders(opts.symbol)
    : await client.getSpotOpenOrders(opts.symbol);
  return (rows || []).map((o) => normalizeOrder(platformId, market, o));
}

/** { supported, status, filledQty, price, avgPrice } — null when unsupported. */
async function orderState(platformId, creds, { market, symbol, orderId }) {
  if (!supportsOrderLookup(platformId)) return null;
  if (!symbol || !orderId) return null;
  const m = String(market || 'SPOT').toUpperCase();
  const client = binanceClient(creds);
  const o = m === 'FUTURES'
    ? await client.getFuturesOrder(symbol, orderId)
    : await client.getSpotOrder(symbol, orderId);
  const n = normalizeOrder(platformId, m, o);
  return { supported: true, ...n };
}

/** Cancel a pending order on the exchange. */
async function cancelPending(platformId, creds, { market, symbol, orderId }) {
  if (!supportsOrderLookup(platformId)) {
    throw new Error(`${platformId} has no cancel connector — remove it from the app list instead`);
  }
  const m = String(market || 'SPOT').toUpperCase();
  const client = binanceClient(creds);
  const o = m === 'FUTURES'
    ? await client.cancelFuturesOrder(symbol, orderId)
    : await client.cancelSpotOrder(symbol, orderId);
  return normalizeOrder(platformId, m, o);
}

/**
 * Is the position/trade still on the exchange?
 * known=false means “this platform cannot be checked”, so the caller must NOT
 * assume the trade is gone.
 */
async function positionStillOpen(platformId, creds, { market, symbol }) {
  if (!supportsOrderLookup(platformId)) return { known: false, exists: null };
  const m = String(market || 'SPOT').toUpperCase();
  const client = binanceClient(creds);
  const sym = String(symbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!sym) return { known: false, exists: null };
  if (m === 'FUTURES') {
    const rows = await client.getFuturesPositionRisk(sym);
    const row = (rows || []).find((p) => String(p.symbol).toUpperCase() === sym);
    if (!row) return { known: true, exists: false };
    return { known: true, exists: Math.abs(+row.positionAmt || 0) > 0 };
  }
  // Spot: a filled buy leaves the coin in the wallet; sold = nothing left.
  let base = null;
  try {
    const f = await client._fetchSpotFilters(sym);
    base = f?.baseAsset || null;
  } catch { /* filters optional */ }
  if (!base) {
    const quote = ['USDT', 'FDUSD', 'USDC', 'BTC', 'ETH', 'BNB', 'TRY', 'EUR', 'BRL', 'TUSD', 'DAI']
      .find((q) => sym.endsWith(q));
    if (quote) base = sym.slice(0, -quote.length);
  }
  if (!base) return { known: false, exists: null };
  const free = await client.getSpotFreeBalance(base);
  if (free == null) return { known: false, exists: null };
  return { known: true, exists: free > 0 };
}

module.exports = {
  testKeys,
  placeOrder,
  closePosition,
  hasRequiredCreds,
  supportsLiveOrders,
  closeMt5,
  supportsOrderLookup,
  listOpenOrders,
  orderState,
  cancelPending,
  positionStillOpen,
  HANDLERS
};

