function userData() { return app.getPath('userData'); }
function keysPath() { return path.join(userData(), 'platform-keys.json'); }
function legacyKeysPath() { return path.join(userData(), 'binance-keys.json'); }
function settingsPath() { return path.join(userData(), 'settings.json'); }
