function journalPath() { return path.join(userData(), 'journal.json'); }
function watchPath() { return path.join(userData(), 'watchlist.json'); }

function mask(s) {
  if (!s || s.length < 8) return '****';
  return `${s.slice(0, 4)}...${s.slice(-4)}`;
}

function loadJson(file, fallback) {
  try {
    if (fs.existsSync(file)) return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {}
  return fallback;
}

function saveJson(file, data) {
  // A transient file lock (antivirus scan / another instance) must never crash
  // startup — otherwise the app can fail to open a window at all.
  try {
    fs.writeFileSync(file, JSON.stringify(data, null, 2), 'utf8');
  } catch (err) {
    try {
      fs.writeFileSync(file, JSON.stringify(data, null, 2), 'utf8');
    } catch {
      console.warn(`saveJson failed for ${file}: ${err.message}`);
    }
  }
}

function loadAllPlatformKeys() {
  let store = loadJson(keysPath(), null);
  if (!store && fs.existsSync(legacyKeysPath())) {
    try {
      const legacy = JSON.parse(fs.readFileSync(legacyKeysPath(), 'utf8'));
      store = { BINANCE: legacy };
      saveJson(keysPath(), store);
    } catch { store = {}; }
  }
  store = store || {};
  if (store.BINANCE?.apiKey) binance.setKeys(store.BINANCE.apiKey, store.BINANCE.apiSecret);
  return store;
}

function getRawKeys(platformId = 'BINANCE') {
  const store = loadAllPlatformKeys();
  return store[platformId] || null;
}

function loadKeys(platformId = 'BINANCE') {
  const store = loadAllPlatformKeys();
  const k = store[platformId];
  const plat = platforms.getPlatform(platformId);
  if (!k) {
    return {
      saved: false,
      platform: platformId,
      platforms: Object.keys(store),
      liveReady: false,
      keyFields: plat?.keyFields || [],
      supportsLive: exchanges.supportsLiveOrders(platformId)
    };
  }
  const liveReady = exchanges.hasRequiredCreds(platformId, k);
  return {
    saved: true,
    platform: platformId,
    apiKey: k.apiKey ? mask(k.apiKey) : '',
    hasSecret: !!k.apiSecret,
    hasPassphrase: !!k.passphrase,
    hasAccountId: !!k.accountId,
    hasLogin: !!k.login,
    hasPassword: !!k.password,
    hasServer: !!k.server,
    liveReady,
    supportsLive: exchanges.supportsLiveOrders(platformId),
    keyFields: plat?.keyFields || [],
    platforms: Object.keys(store)
  };
}

function savePlatformKeys(platformId, fields) {
  const store = loadAllPlatformKeys();
  const prev = store[platformId] || {};
  // keep previous secret/pass/password if user left blank on re-save
  const merged = { ...prev, ...fields, updatedAt: new Date().toISOString() };
  if (!fields.apiSecret && prev.apiSecret) merged.apiSecret = prev.apiSecret;
  if (!fields.passphrase && prev.passphrase) merged.passphrase = prev.passphrase;
  if (!fields.password && prev.password) merged.password = prev.password;
  store[platformId] = merged;
  saveJson(keysPath(), store);
  if (platformId === 'BINANCE' && merged.apiKey && merged.apiSecret) {
    binance.setKeys(merged.apiKey, merged.apiSecret);
    saveSettings({ binanceApiKeyReminderAt: merged.updatedAt });
  }
  return loadKeys(platformId);
}

function clearPlatformKeys(platformId) {
  const store = loadAllPlatformKeys();
  delete store[platformId];
  saveJson(keysPath(), store);
  if (platformId === 'BINANCE') binance.setKeys('', '');
  return { ok: true };
}

function loadSettings() { return loadJson(settingsPath(), {}); }
function saveSettings(data) {
  const next = { ...loadSettings(), ...data };
  saveJson(settingsPath(), next);
  return next;
}

function persistTrades() { saveJson(tradesPath(), openTrades); }
function persistJournal() { saveJson(journalPath(), journal.slice(-500)); }
function persistWatch() { saveJson(watchPath(), watchlist); }

function notificationsEnabled() {
  const s = loadSettings();
  return s.notificationsEnabled !== false;
}

function uiLang() {
  return loadSettings().uiLang || 'en';
}

function notify(title, body, sound = true, kind) {
  // The notification toggle is the single switch: when it is off nothing pops up.
  if (!notificationsEnabled()) return;
  if (Notification.isSupported()) {
    new Notification({ title, body }).show();
  }
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('notification', { title, body, sound, kind: kind || '', at: Date.now() });
  }
}

/** Localized notification — follows settings.uiLang (synced when user changes Language) */
function notifyI18n(titleKey, bodyKey, params = {}, sound = true, kind) {
  const lang = uiLang();
  const p = params || {};
  const title = tNotif(lang, titleKey, p);
  const body = bodyKey ? tNotif(lang, bodyKey, p) : (p._body || '');
  notify(title, body, sound !== false, kind);
}

const API_KEY_REVIEW_DAYS = 25;
const DAY_MS = 24 * 60 * 60 * 1000;

function checkBinanceApiKeyReminder() {
  const key = getRawKeys('BINANCE');
  const savedAt = Date.parse(key?.updatedAt || '');
  if (!key?.apiKey || !Number.isFinite(savedAt)) return;

  const now = Date.now();
  const settings = loadSettings();
  // Do not burn the "already reminded" stamp while notifications are muted.
  if (settings.notificationsEnabled === false) return;
  const lastReminderAt = Date.parse(settings.binanceApiKeyReminderAt || key.updatedAt);
  if (now - savedAt < API_KEY_REVIEW_DAYS * DAY_MS) return;
  if (Number.isFinite(lastReminderAt) && now - lastReminderAt < API_KEY_REVIEW_DAYS * DAY_MS) return;

  const ageDays = Math.floor((now - savedAt) / DAY_MS);
  notifyI18n('n_api_key_reminder_title', 'n_api_key_reminder_body', { ageDays }, false, 'api-key-reminder');
  saveSettings({ binanceApiKeyReminderAt: new Date(now).toISOString() });
}

function startBinanceApiKeyReminder() {
  if (apiKeyReminderTimer) clearInterval(apiKeyReminderTimer);
  setTimeout(checkBinanceApiKeyReminder, 8000);
  apiKeyReminderTimer = setInterval(checkBinanceApiKeyReminder, 6 * 60 * 60 * 1000);
}

function announceStrongSignals(results, market) {
  const tradable = results.filter((r) => (r.type === 'BUY' || r.type === 'SELL'));
  // HIGHER STRONG = base STRONG confirmed by the higher timeframe — notify it on its own
  // with a distinct sound/panel so it is never mixed up with a plain STRONG signal.
  const higher = tradable.filter((r) => r.grade === 'HIGHER STRONG').slice(0, 3);
  for (const s of higher) {
    notifyI18n('n_higher_signal', 'n_buy_body', {
      m: `${market} ${s.type}`,
      symbol: s.symbol,
      price: s.price,
      tp1: s.tp1,
      sl: s.sl
    }, true, 'higher-strong');
  }
  const strong = tradable
    .filter((r) => r.grade === 'STRONG')
    .slice(0, 3);
  for (const s of strong) {
    notifyI18n('n_buy_signal', 'n_buy_body', {
      m: `${market} ${s.grade} ${s.type}`,
      symbol: s.symbol,
      price: s.price,
      tp1: s.tp1,
      sl: s.sl
    }, true, 'strong');
  }
}

function resolveAppRoot() {
  // Prefer folder that contains package.json (project root)
  const candidates = [
    path.join(__dirname, '..'),
    process.cwd(),
    app.getAppPath()
  ];
  for (const c of candidates) {
    try {
      if (c && fs.existsSync(path.join(c, 'package.json')) && fs.existsSync(path.join(c, 'src', 'main.js'))) {
        return path.resolve(c);
      }
    } catch { /* next */ }
  }
  return path.resolve(path.join(__dirname, '..'));
}

function shortcutTarget() {
  const appRoot = resolveAppRoot();
  if (app.isPackaged) {
    return { target: process.execPath, arguments: '', workDir: path.dirname(process.execPath) };
  }
  // Prefer local electron.exe next to project (stable)
  const localElectron = path.join(appRoot, 'node_modules', 'electron', 'dist', 'electron.exe');
  const exe = fs.existsSync(localElectron) ? localElectron : process.execPath;
  /**
   * IMPORTANT (paths with spaces like "website mdtu"):
   * Do NOT pass the full folder as Arguments — Electron often fails with
   * "Unable to find Electron app / Cannot find module <folder>".
   * Use WorkingDirectory = project root and Arguments = "." instead.
   */
  return {
    target: exe,
    arguments: '.',
    workDir: appRoot,
    appRoot
  };
}

function createWindowsShortcuts() {
  if (process.platform !== 'win32') {
    return Promise.resolve({ ok: false, message: 'Shortcuts supported on Windows' });
  }
  const { target, arguments: linkArgs, workDir, appRoot } = shortcutTarget();
  const desktop = path.join(os.homedir(), 'Desktop', 'CPE Trade Pro.lnk');
  const startMenu = path.join(
    process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming'),
    'Microsoft', 'Windows', 'Start Menu', 'Programs', 'CPE Trade Pro.lnk'
  );
  const vbsPath = path.join(workDir || appRoot || resolveAppRoot(), 'START-CPE-Trade-Pro.vbs');
  const batPath = path.join(workDir || appRoot || resolveAppRoot(), 'START-CPE-Trade-Pro.bat');
  // Prefer VBS launcher on Desktop too (handles spaces + no CMD)
  const desktopVbsLnk = path.join(os.homedir(), 'Desktop', 'CPE Trade Pro (Safe).lnk');

  // NOTE: never name a PowerShell param $args — reserved automatic variable
  const esc = (s) => String(s || '').replace(/'/g, "''");
  const psClean = `
$ErrorActionPreference = 'Stop'
$W = New-Object -ComObject WScript.Shell
function Make-CpeShortcut([string]$LinkPath, [string]$TargetExe, [string]$LinkArguments, [string]$WorkDir) {
  $s = $W.CreateShortcut($LinkPath)
  $s.TargetPath = $TargetExe
  $s.Arguments = $LinkArguments
  $s.WorkingDirectory = $WorkDir
  $s.WindowStyle = 1
  $s.Description = 'CPE Trade Pro — Crypto Profit Eye'
  $s.Save()
}
# Main shortcut: electron.exe + "." with WorkingDirectory = project (space-safe)
Make-CpeShortcut -LinkPath '${esc(desktop)}' -TargetExe '${esc(target)}' -LinkArguments '${esc(linkArgs)}' -WorkDir '${esc(workDir)}'
Make-CpeShortcut -LinkPath '${esc(startMenu)}' -TargetExe '${esc(target)}' -LinkArguments '${esc(linkArgs)}' -WorkDir '${esc(workDir)}'
# Backup: VBS silent launcher (best for paths with spaces)
if (Test-Path '${esc(vbsPath)}') {
  Make-CpeShortcut -LinkPath '${esc(desktopVbsLnk)}' -TargetExe 'wscript.exe' -LinkArguments '"${esc(vbsPath)}"' -WorkDir '${esc(workDir)}'
}
Write-Output 'OK'
`;
  return new Promise((resolve) => {
    execFile(
      'powershell.exe',
      ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', psClean],
      { windowsHide: true, timeout: 20000 },
      (err) => {
        if (err) return resolve({ ok: false, message: err.message });
        resolve({
          ok: true,
          desktop,
          startMenu,
          desktopSafe: desktopVbsLnk,
          target,
          arguments: linkArgs,
          workDir,
          batPath,
          message: 'Shortcuts fixed for paths with spaces. Use “CPE Trade Pro” or “CPE Trade Pro (Safe)” on Desktop.'
        });
      }
    );
  });
}

async function maybeAskShortcuts() {
  const s = loadSettings();
  if (!mainWindow || mainWindow.isDestroyed()) return;
  // Force recreate when old .lnk passed full path with spaces → Electron "Cannot find module"
  if (!s.shortcutFix2026c) {
    const r = await createWindowsShortcuts();
    saveSettings({ shortcutFix2026c: true, shortcutFix2026: true, shortcutsAsked: true });
    if (r.ok) {
      notify(
        'Desktop shortcut fixed',
        'Space-in-path error fixed. Close any error box, then open “CPE Trade Pro” (or Safe) from Desktop.',
        false
      );
    }
    return;
  }
  if (s.shortcutsAsked) return;
  const result = await dialog.showMessageBox(mainWindow, {
    type: 'question',
    buttons: ['Yes — create shortcuts', 'No thanks'],
    defaultId: 0,
    cancelId: 1,
    title: 'CPE Trade Pro',
    message: 'Create Desktop and Start Menu shortcuts?',
    detail:
      'Shortcuts let you open CPE Trade Pro from the Desktop or Windows Start. You can also pin the Start Menu item to the taskbar (right-click → Pin to taskbar).'
  });
  saveSettings({ shortcutsAsked: true });
  if (result.response === 0) {
    const r = await createWindowsShortcuts();
    if (r.ok) {
      notify('Shortcuts ready', r.message, false);
    } else {
      dialog.showMessageBox(mainWindow, {
        type: 'warning',
        message: 'Could not create shortcuts',
        detail: r.message || 'Unknown error'
      });
    }
  }
}

