function startMonitors() {
  if (monitorTimer) clearInterval(monitorTimer);
  monitorTimer = setInterval(runMonitors, 15000);
  runMonitors();
}

async function runMonitors() {
  // Candle-close window alarms (5 min before)
  for (const iv of ['15m', '30m', '1h', '4h', '1d']) {
    const eta = candleCloseEta(iv);
    if (eta.remainingMs <= 5 * 60 * 1000 && eta.remainingMs > 4 * 60 * 1000) {
      const key = `${iv}-${Math.floor(Date.now() / eta.intervalMs)}`;
      if (!lastCandleWarn[key]) {
        lastCandleWarn[key] = true;
        notifyI18n('n_candle_close_title', 'n_candle_close', { iv }, true);
      }
    }
  }

  // Upcoming listings — announce the moment an announced coin opens for trading.
  await checkUpcomingListingNotifs();

  // Open trade TP / SL monitor (partial scale-out supported)
  for (const t of [...openTrades]) {
    // LIMIT orders accepted but not yet filled: promote / drop according to the exchange.
    if (t.status === 'PENDING') {
      try { await reconcilePendingTrade(t); } catch { /* keep it pending */ }
      if (t.status !== 'OPEN') continue;
    }
    // SL_ALERT trades wait for a user decision — the monitor must not manage them.
    if (t.status !== 'OPEN') continue;
    try {
      const price = await getLastPrice(t);
      if (price == null) continue;
      t.lastPrice = price;
      const side = t.side || 'BUY';
      const long = side === 'BUY';

      // Take-profit approach hints (50% / 75% / 90% of the move entry → TP1)
      emitTpApproachHints(t, price, long);

      // Trailing TP + SL: BUY → levels move up; SELL → levels move down
      applyTrailingLevels(t, price, long);

      // Auto TP only if trade still has autoClose enabled (user can switch to manual)
      const doAuto = t.autoClose !== false && (autoTradeConfig.autoTakeProfit || t.auto);

      // Take-profit levels — supports many levels (t.tps) and falls back to tp1/tp2
      const tps = tradeTpLevels(t, long);
      let tpNo = 0;
      let behind = +t.entry || 0;
      for (const lvl of tps) {
        tpNo += 1;
        if (lvl.hit) { behind = lvl.price; continue; }
        if (t.status !== 'OPEN') break;
        const crossed = long ? price >= lvl.price : price <= lvl.price;
        if (!crossed) continue;
        markTpHit(t, lvl);
        t.slBreachCount = 0;
        notifyI18n('n_tp1', 'n_tp1_at', { symbol: t.symbol, price, tp1: lvl.price }, true);
        // Bring SL right behind the profit: lock to the previously reached level
        // (entry after TP1, TP1 after TP2, ...). rideBands may only tighten further.
        if (behind > 0) {
          if (long && (t.sl == null || +t.sl < behind)) t.sl = +behind.toFixed(8);
          if (!long && (t.sl == null || +t.sl > behind)) t.sl = +behind.toFixed(8);
        }
        behind = lvl.price;
        if (doAuto) {
          const pct = lvl.pct > 0 ? lvl.pct : 100;
          await closeTradePartial(t, price, `TP${tpNo}`, pct);
        }
      }
      if (t.status === 'OPEN' && t.sl != null) {
        await maybeHitStopLoss(t, price, long, doAuto);
      }
      // Martingale ladder: add a rung only on an adverse move + a fresh same-side signal.
      if (t.status === 'OPEN' && t.martEnabled) {
        await maybeMartingaleAdd(t, price);
      }
    } catch {}
  }
  persistTrades();
  mainWindow?.webContents.send('trades:update', openTrades);
  try {
    const changed = await signalLab.tick(
      (t) => getLastPrice(t),
      (t) => captureSignalChart(t)
    );
    if (changed) mainWindow?.webContents.send('signallab:update');
  } catch { /* paper signal book must not stop the live monitor */ }
}

async function captureSignalChart(t) {
  let rows = [];
  if (t.market === 'FOREX') rows = await platforms.getForexKlines(t.symbol, 80);
  else if (t.market === 'FUTURES') rows = parseKlines(await binance.getFuturesKlines(t.symbol, t.interval || '1d', 80));
  else rows = parseKlines(await binance.getSpotKlines(t.symbol, t.interval || '1d', 80));
  return signalLab.compactFromCandles(rows);
}

/**
 * Anti-hunt SL: ignore single wick touches.
 * Need consecutive breaches past SL + small buffer before closing.
 */
async function maybeHitStopLoss(t, price, long, doAuto) {
  const sl = +t.sl;
  if (!sl || !price) return;
  const need = Math.max(1, Math.min(5, +(t.slConfirmTicks != null ? t.slConfirmTicks : autoTradeConfig.slConfirmTicks) || 2));
  const bufPct = Math.max(0, Math.min(2, +(t.slBufferPct != null ? t.slBufferPct : autoTradeConfig.slBufferPct) || 0.15));
  const buf = sl * (bufPct / 100);
  const breached = long ? price <= sl - buf : price >= sl + buf;
  if (!breached) {
    t.slBreachCount = 0;
    return;
  }
  t.slBreachCount = (t.slBreachCount || 0) + 1;
  if (t.slBreachCount < need) {
    // Soft warn once while confirming — do not close yet
    if (t.slBreachCount === 1) {
      notifyI18n('n_sl', 'n_sl_at', { symbol: t.symbol, price, sl: t.sl }, false);
    }
    return;
  }
  notifyI18n('n_sl', 'n_sl_at', { symbol: t.symbol, price, sl: t.sl }, true);
  if (doAuto) await closeTradePartial(t, price, 'SL', 100);
  else t.status = 'SL_ALERT';
  t.slBreachCount = 0;
}

/**
 * Trailing TP + SL — profit-first, anti stop-hunt:
 * - Wider default trail (~1.2%) so normal wicks do not tag SL
 * - Trail arms only after favorable move (trailArmPct)
 * - SL only moves in the profit direction; never tighter than initial until armed
 */
function applyTrailingLevels(t, price, long) {
  const trailOn = t.trailingStop !== false && (t.trailingStop === true || autoTradeConfig.trailingStop);
  if (!trailOn) return;
  const entry = +t.entry;
  if (!entry || !price) return;
  const prevSl = +t.sl || 0;
  signalLab.rideBands(t, price);
  if (long && prevSl && prevSl < entry && +t.sl >= entry) {
    notifyI18n('n_sl_trail', 'n_sl_trail_body', { symbol: t.symbol, sl: t.sl }, false);
  }
}

function announceBbLower(list, market) {
  const rows = (list || []).filter((s) => s.bollinger?.touchLower && s.type !== 'SELL').slice(0, 3);
  for (const s of rows) {
    notify(
      `BB Lower · ${market}`,
      `${s.symbol} is at the lower band. A BUY confirmation can ride toward the upper band.`,
      true,
      'strong'
    );
  }
}

function onBand(sig) {
  const b = sig.bollinger || {};
  const ctx = sig.context || {};
  const p = +sig.price || +sig.entry;
  if (!p) return false;
  const near = (lvl) => lvl && Math.abs(p - +lvl) / p <= 0.02;
  if (sig.type === 'BUY') {
    if (b.touchLower || near(b.lower) || near(b.mid)) return true;
    // Trend-following longs: an intact uptrend pullback or a confirmed turn is
    // tradeable even when price is not sitting on the lower band.
    return (ctx.trend === 'UP' && !ctx.toppedOut) || ctx.turn === 'UP';
  }
  if (sig.type === 'SELL') {
    if (b.touchUpper || near(b.upper) || near(b.mid)) return true;
    return (ctx.trend === 'DOWN' && !ctx.bottomedOut) || ctx.turn === 'DOWN';
  }
  return false;
}

function signalQualityIssue(sig, market) {
  const side = String(sig?.type || sig?.side || '').toUpperCase();
  if (side !== 'BUY' && side !== 'SELL') return 'signal side is missing';
  if (sig.grade !== 'STRONG' && sig.grade !== 'HIGHER STRONG' && sig.grade !== 'CAUTION') return 'signal grade is missing';
  const directionalScore = side === 'SELL' ? -(+sig.score || 0) : (+sig.score || 0);
  // Match the minimum that analysis.js already needs to call this signal STRONG
  // (score>=6 normally, or score>=4 when price sits on the band) / CAUTION (>=3).
  const minScore = sig.grade === 'STRONG' || sig.grade === 'HIGHER STRONG' ? 4 : 3;
  if (directionalScore < minScore) return `directional score is below ${minScore}`;

  const entry = +sig.entry || +sig.price;
  const sl = +sig.sl;
  const targets = [+sig.tp1, +sig.tp2].filter((v) => Number.isFinite(v) && v > 0);
  if (!(entry > 0) || !(sl > 0) || !targets.length) return 'valid entry, stop-loss and take-profit are required';

  const risk = side === 'BUY' ? entry - sl : sl - entry;
  const rewardPrices = targets
    .map((target) => side === 'BUY' ? target - entry : entry - target)
    .filter((v) => v > 0);
  if (!(risk > 0) || !rewardPrices.length) return 'stop-loss or take-profit is on the wrong side';

  const feePct = market === 'FUTURES' ? 0.08 : market === 'FOREX' ? 0.03 : 0.2;
  const netReward = (Math.max(...rewardPrices) / entry) * 100 - feePct;
  const riskPct = (risk / entry) * 100;
  if (!(netReward > 0) || netReward / riskPct < 1.5) return 'net reward/risk is below 1.5:1 after estimated fees';
  return '';
}

/** Soft hints while trade is running — approaching take profit */
function emitTpApproachHints(t, price, long) {
  if (t.tp1 == null || t.entry == null || t.hitTp1) return;
  const entry = +t.entry;
  const tp1 = +t.tp1;
  const span = Math.abs(tp1 - entry);
  if (span < 1e-12) return;
  let progress;
  if (long) {
    if (price <= entry) return;
    progress = (price - entry) / (tp1 - entry);
  } else {
    if (price >= entry) return;
    progress = (entry - price) / (entry - tp1);
  }
  t.tpProgress = Math.max(0, Math.min(1, progress));
  for (const level of [0.5, 0.75, 0.9]) {
    if (progress >= level) {
      const key = `${t.id}|${level}`;
      if (!lastTpHint[key]) {
        lastTpHint[key] = true;
        const pct = Math.round(level * 100);
        notify(
          `TP Hint ${pct}%`,
          `${t.symbol}: → TP1 ${formatHint(tp1)} · ${pct}%`,
          true
        );
        mainWindow?.webContents.send('tp:hint', {
          id: t.id,
          symbol: t.symbol,
          level: pct,
          price,
          tp1,
          progress: t.tpProgress
        });
      }
    }
  }
}

function formatHint(n) {
  if (n == null) return '—';
  if (Math.abs(n) >= 1) return (+n).toFixed(4);
  return (+n).toPrecision(6);
}

/**
 * Short-lived per-market price maps. The signal book can hold many rows, so we
 * price them from one bulk ticker call instead of one request per symbol.
 */
const priceMapCache = {};
const PRICE_MAP_TTL_MS = 5000;

async function bulkPriceMap(market, platform) {
  const key = (platform === 'FOREX' || market === 'FOREX') ? 'FOREX' : market;
  const now = Date.now();
  const cached = priceMapCache[key];
  if (cached && now - cached.at < PRICE_MAP_TTL_MS) return cached.map;
  let map;
  if (key === 'FOREX') {
    const ticks = await platforms.getForexTickers();
    map = new Map((ticks || []).map((x) => [x.symbol, +x.price]));
  } else if (key === 'FUTURES') {
    const ticks = await binance.getFuturesTicker24h();
    map = new Map((ticks || []).map((x) => [x.symbol, +(x.lastPrice != null ? x.lastPrice : x.price)]));
  } else {
    const ticks = await binance.getSpotTicker24h();
    map = new Map((ticks || []).map((x) => [x.symbol, +(x.lastPrice != null ? x.lastPrice : x.price)]));
  }
  priceMapCache[key] = { at: now, map };
  return map;
}

async function getLastPrice(t) {
  const platform = t.platform || 'BINANCE';
  const market = t.market || 'SPOT';
  try {
    const map = await bulkPriceMap(market, platform);
    const hit = map.get(t.symbol);
    if (hit != null && Number.isFinite(hit)) return hit;
  } catch { /* fall through to a single-symbol lookup */ }
  if (platform === 'FOREX' || market === 'FOREX') {
    const ticks = await platforms.getForexTickers();
    const hit = ticks.find((x) => x.symbol === t.symbol);
    return hit ? hit.price : null;
  }
  if (market === 'FUTURES') {
    const px = await binance.getFuturesPrice(t.symbol);
    return +px.price;
  }
  const px = await binance.getSpotPrice(t.symbol);
  return +px.price;
}

function roundQty(q) {
  if (q >= 1) return Math.floor(q * 1000) / 1000;
  if (q >= 0.01) return Math.floor(q * 10000) / 10000;
  return Math.floor(q * 1e6) / 1e6;
}

/**
 * Close part or all of a position.
 * pct = 1–100 of remaining qty. Live exchange order when keys + not paper.
 */
async function closeTradePartial(t, price, reason, pct = 100) {
  const remain = t.qtyRemain != null ? +t.qtyRemain : +t.qty;
  if (!remain || remain <= 0) {
    t.status = reason;
    journalPush(t, price, reason, 0);
    return { ok: true };
  }
  const usePct = Math.min(100, Math.max(1, +pct || 100));
  let closeQty = roundQty(remain * (usePct / 100));
  if (closeQty <= 0) closeQty = remain;
  if (closeQty > remain) closeQty = remain;

  const platform = t.platform || 'BINANCE';

  // --- Live exchange close -------------------------------------------------
  // Only for trades that really live on an exchange. A rejected close must NEVER
  // be swallowed: keep the trade OPEN so the user can see why and retry.
  if (!t.paper && platform !== 'FOREX_DEMO' && exchanges.supportsLiveOrders(platform)) {
    const creds = getRawKeys(platform);
    if (!exchanges.hasRequiredCreds(platform, creds)) {
      const msg = `No API keys saved for ${platform} — the ${platform} position was NOT closed`;
      notifyI18n('n_close_err', null, { _body: `${t.symbol}: ${msg}` }, true, 'error');
      return { ok: false, error: msg };
    }
    try {
      const order = await exchanges.closePosition(platform, creds, {
        market: t.market,
        symbol: t.symbol,
        side: t.side || 'BUY',
        quantity: closeQty,
        pct: usePct,
        lots: usePct >= 100
          ? undefined
          : (t.forexLots != null ? +(t.forexLots * (usePct / 100)).toFixed(2) : undefined),
        forexLots: t.forexLots,
        marginType: t.marginType,
        leverage: t.leverage
      });
      // The exchange is the source of truth: it may have filled a slightly
      // different size (e.g. capped to the real wallet balance), so book the
      // exact amount that was sold.
      const filled = order && order.executedQty != null ? +order.executedQty : NaN;
      if (Number.isFinite(filled) && filled > 0) closeQty = roundQty(filled);
    } catch (e) {
      const msg = e.message || String(e);
      notifyI18n('n_close_err', null, { _body: `${t.symbol}: ${msg}` }, true, 'error');
      return { ok: false, error: msg };
    }
  }
  // Forex demo / paper: tracked only

  try {
    const left = roundQty(remain - closeQty);
    const pnlPct = t.entry ? (((price - t.entry) / t.entry) * 100) * ((t.side || 'BUY') === 'BUY' ? 1 : -1) : 0;
    journal.unshift({
      symbol: t.symbol,
      market: t.market,
      platform,
      entry: t.entry,
      exit: price,
      qty: closeQty,
      reason: `${reason}${usePct < 100 ? ` partial ${usePct}%` : ''}`,
      pnlPct,
      at: new Date().toISOString(),
      openedAt: t.openedAt || null,
      side: t.side || 'BUY',
      leverage: t.leverage || 1,
      sl: t.sl != null ? t.sl : null,
      tp1: t.tp1 != null ? t.tp1 : null,
      tp2: t.tp2 != null ? t.tp2 : null,
      tps: Array.isArray(t.tps) ? t.tps : null,
      partial: usePct < 100,
      tradeId: t.id || null,
      tradeClosed: left <= 0 || usePct >= 100,
      paper: !!t.paper,
      ...signalJournalFields(t, pnlPct)
    });
    persistJournal();

    if (left <= 0 || usePct >= 100) {
      t.qtyRemain = 0;
      t.status = reason;
      t.closedAt = new Date().toISOString();
      t.closePrice = price;
      openTrades = openTrades.filter((x) => x.id !== t.id);
      notifyI18n('n_trade_closed', 'n_trade_closed_body', { symbol: t.symbol, price, reason }, true);
    } else {
      t.qtyRemain = left;
      t.partials = (t.partials || 0) + 1;
      notifyI18n('n_partial_tp', 'n_partial_body', { symbol: t.symbol, pct: usePct, qty: closeQty, left }, true);
    }
    persistTrades();
    mainWindow?.webContents.send('trades:update', openTrades);
    return { ok: true, left: t.qtyRemain, closed: closeQty };
  } catch (e) {
    notifyI18n('n_close_err', null, { _body: `${t.symbol}: ${e.message}` }, true, 'error');
    return { ok: false, error: e.message };
  }
}

/** Normalized, ordered take-profit levels. Supports many levels via t.tps. */
function tradeTpLevels(t, long) {
  let levels = [];
  if (Array.isArray(t.tps) && t.tps.length) {
    levels = t.tps
      .filter((x) => x && +x.price > 0)
      .map((x) => ({ price: +x.price, pct: +x.pct > 0 ? +x.pct : 0, hit: !!x.hit, ref: x }));
  } else {
    if (t.tp1 != null && +t.tp1 > 0) levels.push({ price: +t.tp1, pct: t.tp1Pct != null ? +t.tp1Pct : 50, hit: !!t.hitTp1, ref: null, key: 'tp1' });
    if (t.tp2 != null && +t.tp2 > 0) levels.push({ price: +t.tp2, pct: t.tp2Pct != null ? +t.tp2Pct : 100, hit: !!t.hitTp2, ref: null, key: 'tp2' });
  }
  levels.sort((a, b) => (long ? a.price - b.price : b.price - a.price));
  return levels;
}

function markTpHit(t, lvl) {
  if (lvl.ref) lvl.ref.hit = true;
  else if (lvl.key === 'tp2') t.hitTp2 = true;
  else t.hitTp1 = true;
}

function signalJournalFields(t, pnlPct) {
  if (!t.fromSignal && t.signalType == null && t.signalScore == null) return {};
  const pnl = +pnlPct || 0;
  return {
    fromSignal: true,
    signalType: t.signalType || t.side || 'BUY',
    signalScore: t.signalScore,
    signalEntry: t.signalEntry || t.entry,
    verdict: pnl > 0.05 ? 'PROFIT' : pnl < -0.05 ? 'LOSS' : 'FLAT'
  };
}

function journalPush(t, price, reason, qty) {
  const pnlPct = t.entry ? (((price - t.entry) / t.entry) * 100) * ((t.side || 'BUY') === 'BUY' ? 1 : -1) : 0;
  journal.unshift({
    symbol: t.symbol,
    market: t.market,
    platform: t.platform || 'BINANCE',
    entry: t.entry,
    exit: price,
    qty: qty != null ? qty : t.qty,
    reason,
    pnlPct,
    at: new Date().toISOString(),
    openedAt: t.openedAt || null,
    side: t.side || 'BUY',
    leverage: t.leverage || 1,
    sl: t.sl != null ? t.sl : null,
    tp1: t.tp1 != null ? t.tp1 : null,
    tp2: t.tp2 != null ? t.tp2 : null,
    tps: Array.isArray(t.tps) ? t.tps : null,
    tradeId: t.id || null,
    tradeClosed: true,
    reasons: t.reasons || [],
    paper: !!t.paper,
    ...signalJournalFields(t, pnlPct)
  });
  persistJournal();
  t.status = reason;
  openTrades = openTrades.filter((x) => x.id !== t.id);
  persistTrades();
}

/** A trade is "broken" when it has no pair, no entry price, or no quantity. */
function isBrokenTrade(t) {
  const sym = (t && (t.symbol || t.pair)) || (t && t.base && t.quote ? `${t.base}${t.quote}` : '');
  return !String(sym).trim() || !(+t.entry > 0) || !(+t.qty > 0);
}

/**
 * Statuses that stay in the app's trade list.
 *  - OPEN      : live position the monitor manages (TP/SL/trailing)
 *  - PENDING   : LIMIT order accepted by the exchange but not yet filled
 *  - SL_ALERT  : SL was hit but auto-close was off — needs the user's decision
 * Anything else (TP1 / SL / MANUAL / …) is a closed trade and leaves the list.
 */
const ACTIVE_STATUS = new Set(['OPEN', 'PENDING', 'SL_ALERT']);
function isActiveTrade(t) {
  return !!t && ACTIVE_STATUS.has(t.status);
}

/** Drop a trade from the app list only (no journal entry, no exchange order). */
function forgetTradeLocal(t) {
  openTrades = openTrades.filter((x) => x.id !== t.id);
  persistTrades();
  mainWindow?.webContents.send('trades:update', openTrades);
}

/** Remove broken trades from the open list. Returns how many were dropped. */
function clearBrokenTrades() {
  const before = openTrades.length;
  openTrades = openTrades.filter((t) => !isBrokenTrade(t));
  const removed = before - openTrades.length;
  if (removed > 0) {
    persistTrades();
    mainWindow?.webContents.send('trades:update', openTrades);
  }
  return { removed, open: openTrades };
}

/**
 * Promote one paper (DEMO) LIMIT order to OPEN once the market price crosses it.
 * A BUY limit fills when price drops to/below the limit; a SELL limit fills when
 * price rises to/above it. Until then it stays PENDING in the Positions list.
 */
async function reconcilePaperPending(t) {
  const limit = +t.pendingPrice;
  if (!(limit > 0)) return;
  let price = null;
  try { price = await getLastPrice(t); } catch { return; }
  if (price == null) return;
  const long = (t.side || 'BUY') === 'BUY';
  const crossed = long ? price <= limit : price >= limit;
  if (!crossed) return;
  t.entry = limit;
  t.peakPrice = limit;
  t.troughPrice = limit;
  t.filledAt = new Date().toISOString();
  t.pendingStatus = 'FILLED';
  t.status = 'OPEN';
  notifyI18n('n_pending_filled', null, { _body: `${t.symbol}: limit order filled @ ${limit}` }, true);
}

/**
 * Reconcile one LIMIT (PENDING) trade with the exchange:
 *  - FILLED / partially filled → promote to OPEN with the real entry + qty
 *  - CANCELED / EXPIRED / REJECTED → drop from the app list
 *  - still NEW → keep waiting (only refresh the pending badge info)
 * Platforms without an order-lookup API are left untouched.
 */
async function reconcilePendingTrade(t) {
  // DEMO/paper limit orders have no exchange to ask — fill them locally when
  // the market price crosses the limit.
  if (t.paper) return reconcilePaperPending(t);
  if (!exchanges.supportsOrderLookup(t.platform) || !t.orderId) return;
  const creds = getRawKeys(t.platform);
  if (!creds || !exchanges.hasRequiredCreds(t.platform, creds)) return;
  let st = null;
  try {
    st = await exchanges.orderState(t.platform, creds, {
      market: t.market,
      symbol: t.symbol,
      orderId: t.orderId
    });
  } catch {
    return; // network / key issue — keep it pending rather than lose the order
  }
  if (!st) return;
  const status = String(st.status || '').toUpperCase();
  t.pendingStatus = status;
  t.pendingPrice = st.price != null ? st.price : t.pendingPrice;
  if (status === 'CANCELED' || status === 'EXPIRED' || status === 'REJECTED') {
    forgetTradeLocal(t);
    notifyI18n('n_pending_cancelled', null, { _body: `${t.symbol}: limit order ${status}` }, true, 'warn');
    return;
  }
  if (+st.filledQty > 0) {
    t.entry = +st.avgPrice > 0 ? +st.avgPrice : t.entry;
    t.qty = +st.filledQty;
    t.qtyRemain = +st.filledQty;
    t.peakPrice = t.entry;
    t.troughPrice = t.entry;
    t.filledAt = new Date().toISOString();
    t.status = 'OPEN';
    notifyI18n('n_pending_filled', null, { _body: `${t.symbol}: limit order filled @ ${t.entry}` }, true);
  }
}

function trackTrade(trade) {
  const qty = trade.qty;
  const entry = trade.entry;
  openTrades.push({
    ...trade,
    id: trade.id || `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    openedAt: trade.openedAt || new Date().toISOString(),
    status: trade.status || 'OPEN',
    side: trade.side || 'BUY',
    platform: trade.platform || 'BINANCE',
    qtyRemain: trade.qtyRemain != null ? trade.qtyRemain : qty,
    autoClose: trade.autoClose !== false,
    tp1Pct: trade.tp1Pct != null ? trade.tp1Pct : autoTradeConfig.tp1Pct,
    tp2Pct: trade.tp2Pct != null ? trade.tp2Pct : autoTradeConfig.tp2Pct,
    trailingStop: trade.trailingStop != null ? trade.trailingStop : !!autoTradeConfig.trailingStop,
    trailPct: trade.trailPct != null ? trade.trailPct : autoTradeConfig.trailPct,
    peakPrice: entry,
    troughPrice: entry
  });
  persistTrades();
  mainWindow?.webContents.send('trades:update', openTrades);
}

async function closeAllOpenTrades(reason = 'TRIAL_END') {
  const list = openTrades.filter((t) => t.status === 'OPEN');
  for (const t of list) {
    try {
      const price = t.lastPrice || t.entry || (await getLastPrice(t));
      await closeTradePartial(t, price, reason, 100);
    } catch {}
  }
  notifyI18n('n_trial_ended', 'n_trial_ended_body', {}, true);
}

function sanitizeAutoTrailConfig(cfg) {
  if (!cfg) return cfg;
  if (cfg.trailPct == null || +cfg.trailPct < 0.4) cfg.trailPct = 1.2;
  if (cfg.trailArmPct == null) cfg.trailArmPct = 0.6;
  if (cfg.slConfirmTicks == null) cfg.slConfirmTicks = 2;
  if (cfg.slBufferPct == null) cfg.slBufferPct = 0.15;
  return cfg;
}

app.whenReady().then(() => {
  loadKeys();
  const s = loadSettings();
  if (s.autoTradeConfig) {
    autoTradeConfig = sanitizeAutoTrailConfig({ ...autoTradeConfig, ...s.autoTradeConfig });
    saveSettings({ autoTradeConfig });
  }
  if (Array.isArray(s.autoTradeSessions)) {
    autoTradeSessions = sanitizeSessions(s.autoTradeSessions);
  } else {
    // First run after upgrade: turn the single legacy config into one session
    autoTradeSessions = sanitizeSessions([{ ...autoTradeConfig, id: makeSessionId() }]);
  }
  saveSettings({ autoTradeSessions });
  signalLab.init(path.join(userData(), 'signal-lab.json'));
  openTrades = loadJson(tradesPath(), []).filter((t) => isActiveTrade(t) && !isBrokenTrade(t));
  // Upgrade open trades that still carry ultra-tight 0.05% trail
  for (const t of openTrades) {
    if (t.trailPct == null || +t.trailPct < 0.4) t.trailPct = 1.2;
    t.slBreachCount = 0;
  }
  persistTrades();
  journal = loadJson(journalPath(), []);
  watchlist = loadJson(watchPath(), []);
  // seed known pairs from settings to detect new listings after restart
  knownSpotPairs = s.knownSpotPairs || [];
  knownFuturesPairs = s.knownFuturesPairs || [];
  // discovered spot listing dates survive restarts (spot exchangeInfo has none)
  spotListingCache = s.spotListingCache || {};
  checkSoftwareIntegrity();
  createWindow();
  startBinanceApiKeyReminder();
  startIpWatch();
  startMonitors();
  startAccessWatch();
  // Bring the local forex bridge up automatically for users who already saved MT5/MT4 credentials.
  if (getRawKeys('FOREX_MT5')) ensureMt5Bridge().catch(() => {});
  else if (getRawKeys('FOREX_MT4')) ensureBridgeProcess().catch(() => {});
  // First run (or a previous failure): install the desktop support software in the
  // background so the customer never has to install Python 3 or a MetaTrader terminal by hand.
  if (!s.mt5Provision?.ok || (getRawKeys('FOREX_MT4') && !s.mt4Provision?.ok)) {
    setTimeout(() => {
      provisionForexEnvironment('startup')
        .then((r) => { (r?.mt5 ? ensureMt5Bridge : ensureBridgeProcess)().catch(() => {}); })
        .catch(() => {});
    }, 8000);
  }
  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

/**
 * Packaged builds ship a signed manifest of every source file. If any of them
 * was edited (patched / cracked) all signals stay blocked.
 */
function checkSoftwareIntegrity() {
  if (!app.isPackaged) return; // source / dev runs are not enforced
  try {
    const res = guard.verifyAppIntegrity(app.getAppPath());
    if (res.ok) return;
    guard.lockTamper(userData(), `INTEGRITY_${res.reason}`, res.files);
    try {
      ownerStore.logActivity(userData(), {
        type: 'TAMPER_LOCK',
        detail: `${res.reason}${res.files ? `: ${res.files.slice(0, 6).join(', ')}` : ''}`
      });
    } catch { /* ignore */ }
  } catch { /* never block startup on a check error */ }
}

function startAccessWatch() {
  if (accessTimer) clearInterval(accessTimer);
  accessTimer = setInterval(async () => {
    const a = enrichStatus(license.checkAccess(userData()));
    if ((a.mode === 'TRIAL_EXPIRED' || a.closeTrades) && a.mode === 'TRIAL_EXPIRED' && !trialClosedOnce) {
      trialClosedOnce = true;
      await closeAllOpenTrades('TRIAL_END');
      mainWindow?.webContents.send('access:expired', a);
    }
    if (a.mode === 'MONTH3_EXPIRED' && !month3ClosedOnce) {
      month3ClosedOnce = true;
      await closeAllOpenTrades('LICENSE_EXPIRED');
      mainWindow?.webContents.send('access:expired', a);
    }
    if (a.mode === 'TRIAL' && a.trial) {
      mainWindow?.webContents.send('access:trial', a.trial);
    }
    if ((a.mode === 'MONTH3' || a.mode === 'MONTH3_GRACE') && a.warnings?.length) {
      const w = a.warnings[0];
      const code = `${w.code}-${w.daysLeft}`;
      if (code !== lastWarnCode) {
        lastWarnCode = code;
        mainWindow?.webContents.send('license:warning', { ...w, mode: a.mode, expiresAt: a.expiresAt, graceEndsAt: a.graceEndsAt });
        notifyI18n('n_license_warn', null, {
          _body: a.message || `${w.code}: ${w.daysLeft} day(s)`
        }, true);
      }
    }
    if (a.mode === 'MONTH3_GRACE') {
      mainWindow?.webContents.send('access:grace', a);
    }
  }, 30000);
}

app.on('window-all-closed', () => {
  if (scanTimer) clearInterval(scanTimer);
  if (monitorTimer) clearInterval(monitorTimer);
  if (apiKeyReminderTimer) clearInterval(apiKeyReminderTimer);
  stopMt5Bridge();
  if (process.platform !== 'darwin') app.quit();
});

// License
ipcMain.handle('license:status', () => enrichStatus(license.checkAccess(userData())));
ipcMain.handle('license:machineId', () => license.getMachineId());
ipcMain.handle('guard:status', () => guard.state(userData()));

/**
 * A bad activation code counts as a strike. Strike 1-2 warn, strike 3 blocks
 * every signal until a genuine owner key is activated.
 */
function strikeResult(code, raw) {
  const g = guard.registerStrike(userData(), { code, keyHint: String(raw || '').slice(0, 28) });
  try {
    ownerStore.logActivity(userData(), {
      type: 'GUARD_STRIKE',
      detail: `${code} — strike ${g.strikes}/${g.maxStrikes}`
    });
  } catch { /* ignore */ }
  const message = g.locked
    ? `🚫 All signals blocked — ${g.maxStrikes} invalid activation codes were entered. Signal generation stays locked until a genuine owner key is activated. WhatsApp ${license.OWNER.whatsapp}.\n\n🚫 සියලුම සංඥා block කර ඇත — වැරදි activation කේත ${g.maxStrikes} වතාවක් ඇතුළත් කර ඇත. නිවැරදි owner key එකක් activate කරන තෙක් සංඥා නිකුත් නොවේ.`
    : `⚠️ Warning ${g.strikes} of ${g.maxStrikes} — that activation code is not valid. ${g.strikesLeft} more wrong attempt(s) will block all signals.\n\n⚠️ අවවාදය ${g.strikes}/${g.maxStrikes} — එම activation කේතය වැරදියි. තව ${g.strikesLeft} වතාවක් වැරදුනොත් සියලුම සංඥා block වේ.`;
  return {
    ok: false,
    message,
    security: true,
    strike: g.strikes,
    strikesLeft: g.strikesLeft,
    locked: g.locked,
    guard: g
  };
}

ipcMain.handle('license:activate', (_e, key) => {
  const raw = String(key || '').trim();
  // Claim / forged reward slips never activate — report to admin
  if (referral.parseClaimSlip?.(raw) || referral.parseRewardKey(raw)) {
    const rr = referral.activateRewardKey(userData(), raw);
    const g = strikeResult('NON_OWNER_SLIP', raw);
    return { ...g, message: `${rr.message || ''} ${g.message}`.trim() };
  }
  const machineId = license.getMachineId();
  const meta = license.detectKeyMeta(raw, machineId);
  if (!meta) {
    if (license.looksLikeForgedKey(raw)) {
      license.reportSecurity(userData(), {
        code: 'FORGED_KEY_ATTEMPT',
        message: 'Forged or wrong-machine key activation blocked',
        keyHint: raw.slice(0, 28)
      });
    }
    return strikeResult('INVALID_OR_FORGED_KEY', raw);
  }
  try {
    license.saveLicense(userData(), raw, meta.plan);
  } catch (e) {
    const g = strikeResult('ACTIVATE_REJECTED', raw);
    return { ...g, message: `${e.message || 'Activation blocked'} ${g.message}`.trim() };
  }
  trialClosedOnce = false;
  month3ClosedOnce = false;
  lastWarnCode = '';
  guard.clearStrikes(userData());
  const proof = referral.issueProof(userData(), 'PURCHASE');
  ownerStore.logActivity(userData(), {
    type: 'LICENSE_ACTIVATE',
    detail: `${meta.plan}${meta.timed ? ` (${meta.days}d timed)` : ''} license activated`
  });
  return {
    ok: true,
    status: enrichStatus(license.checkAccess(userData())),
    referralProof: proof.ok ? proof.proof : null
  };
});
ipcMain.handle('license:startTrial', () => {
  const cur = license.checkAccess(userData());
  if (cur.mode === 'LIFETIME' || cur.mode === 'MONTH3' || cur.mode === 'MONTH3_GRACE' || cur.mode === 'FULL') {
    return { ok: true, status: enrichStatus(cur) };
  }
  if (cur.mode === 'TRIAL') return { ok: true, status: enrichStatus(cur) };
  if (cur.mode === 'TRIAL_EXPIRED' || cur.mode === 'MONTH3_EXPIRED') {
    return {
      ok: false,
      message: cur.message,
      status: enrichStatus(cur)
    };
  }
  license.startTrial(userData());
  trialClosedOnce = false;
  const proof = referral.issueProof(userData(), 'TRIAL');
  ownerStore.logActivity(userData(), { type: 'TRIAL_START', detail: `${license.TRIAL_DAYS}-day free trial started` });
  return {
    ok: true,
    status: enrichStatus(license.checkAccess(userData())),
    referralProof: proof.ok ? proof.proof : null
  };
});
/** Signals are blocked while the guard is locked — 3 bad keys or an edited build. */
function signalsBlocked() {
  const g = guard.state(userData());
  return g.locked ? g : null;
}

function blockedMessage(g) {
  return g.tamper
    ? 'Signals blocked — the software files were modified. Reinstall the original CPE Trade Pro setup, or contact the owner.'
    : `Signals blocked — ${g.maxStrikes} invalid activation codes were entered. Activate a genuine owner key to unlock.`;
}

function enrichStatus(a) {
  const pub = ownerStore.getPublicConfig(userData());
  const month3Usd = pub.month3Usd || a.month3Usd || license.PRICE_MONTH3_USD;
  const lifetimeUsd = pub.priceUsd || pub.lifetimeUsd || a.lifetimeUsd || license.PRICE_LIFETIME_USD;
  return {
    ...a,
    guard: guard.state(userData()),
    priceUsd: lifetimeUsd,
    month3Usd,
    lifetimeUsd,
    lifetime: true,
    lifetimeLabel: pub.lifetimeLabel || 'Lifetime license (one-time)',
    month3Label: pub.month3Label || '3-month license',
    trialDays: a.trialDays || pub.trialDays || license.TRIAL_DAYS,
    graceDays: a.graceDays || license.GRACE_DAYS,
    publicConfig: {
      ...pub,
      month3Usd,
      lifetimeUsd,
      priceUsd: lifetimeUsd
    }
  };
}
ipcMain.handle('license:price', async (_e, currency) => {
  const pub = ownerStore.getPublicConfig(userData());
  const month3Usd = pub.month3Usd || license.PRICE_MONTH3_USD;
  const lifetimeUsd = pub.priceUsd || pub.lifetimeUsd || license.PRICE_LIFETIME_USD;
  const cur = (currency || 'USD').toUpperCase();
  const base = {
    month3Usd,
    lifetimeUsd,
    usd: lifetimeUsd,
    lifetime: true,
    lifetimeLabel: pub.lifetimeLabel,
    payments: pub.payments
  };
  const convert = async (usd) => {
    if (cur === 'USD') return { local: usd, rate: 1 };
    try {
      const axios = require('axios');
      const res = await axios.get(`https://api.frankfurter.app/latest?from=USD&to=${cur}`, { timeout: 10000 });
      const rate = res.data?.rates?.[cur];
      if (!rate) return { local: null, rate: null, error: 'Currency not available' };
      return { local: +(usd * rate).toFixed(2), rate };
    } catch (e) {
      return { local: null, rate: null, error: e.message };
    }
  };
  const m = await convert(month3Usd);
  const l = await convert(lifetimeUsd);
  return {
    ...base,
    currency: cur,
    month3Local: m.local,
    lifetimeLocal: l.local,
    local: l.local,
    rate: l.rate || m.rate,
    error: l.error || m.error
  };
});
