const HIGHER_INTERVAL = {
  '1m': '5m',
  '3m': '15m',
  '5m': '15m',
  '15m': '1h',
  '30m': '4h',
  '1h': '4h',
  '2h': '1d',
  '4h': '1d',
  '1d': '1w',
  '1w': '1M'
};

/** Group lower-timeframe candles into a higher timeframe (FOREX feed is daily-only). */
function aggregateKlines(candles, groupSize) {
  const out = [];
  const n = Math.max(1, Math.floor(groupSize) || 1);
  for (let i = 0; n > 0 && i + n <= candles.length; i += n) {
    const chunk = candles.slice(i, i + n);
    out.push({
      openTime: chunk[0].openTime,
      open: chunk[0].open,
      high: Math.max(...chunk.map((c) => c.high)),
      low: Math.min(...chunk.map((c) => c.low)),
      close: chunk[chunk.length - 1].close,
      volume: chunk.reduce((s, c) => s + (+c.volume || 0), 0),
      closeTime: chunk[chunk.length - 1].closeTime
    });
  }
  return out;
}

async function addHigherTimeframeConfirmation(signal, market, interval, baseCandles) {
  if (!signal || signal.grade !== 'STRONG'
    || (signal.type !== 'BUY' && signal.type !== 'SELL')) return signal;

  try {
    if (market === 'FOREX') {
      // Forex feed is daily-only: build the weekly bars from the daily candles we already have.
      const daily = baseCandles?.length ? baseCandles : await platforms.getForexKlines(signal.symbol, 180);
      const weekly = aggregateKlines(daily.filter((c) => (c.closeTime || 0) < Date.now()), 5);
      if (weekly.length < 20) return signal;
      return applyHigherTimeframeConfirmation(signal, analyzeSymbol(signal.symbol, weekly, 'FOREX', '1w'));
    }

    const higherInterval = HIGHER_INTERVAL[interval];
    if (!higherInterval) return signal;
    const raw = market === 'FUTURES'
      ? await binance.getFuturesKlines(signal.symbol, higherInterval, 120)
      : await binance.getSpotKlines(signal.symbol, higherInterval, 120);
    // Ignore the still-forming candle so this confirmation does not repaint.
    const candles = parseKlines(raw).filter((c) => c.closeTime < Date.now());
    if (candles.length < 60) return signal;
    const higher = analyzeSymbol(signal.symbol, candles, market, higherInterval);
    return applyHigherTimeframeConfirmation(signal, higher);
  } catch {
    // If the secondary timeframe feed is unavailable, preserve the base signal.
    return signal;
  }
}

/* ---- Market sentiment (futures funding rate + Fear & Greed) --------------
 * Funding comes from one bulk futures call (cached ~5 min); Fear & Greed is
 * shared from the news module (cached ~30 min). Attached to SPOT/FUTURES
 * signals only — it can soften a fresh STRONG, never upgrade one. */
let fundingCache = { at: 0, map: {} };

async function getFundingMap() {
  if (Date.now() - fundingCache.at < 5 * 60 * 1000 && Object.keys(fundingCache.map).length) {
    return fundingCache.map;
  }
  try {
    const rows = await binance.getFuturesFundingRates();
    const map = {};
    for (const r of Array.isArray(rows) ? rows : []) {
      if (r?.symbol) map[r.symbol] = +r.lastFundingRate;
    }
    if (Object.keys(map).length) fundingCache = { at: Date.now(), map };
  } catch { /* keep previous snapshot */ }
  return fundingCache.map;
}

async function enrichSentiment(list, market) {
  if (!Array.isArray(list) || !list.length || market === 'FOREX') return list;
  const fearGreed = await news.getFearGreedIndex().catch(() => null);
  const funding = market === 'FUTURES' ? await getFundingMap() : null;
  for (const s of list) {
    const fundingRate = funding && s.symbol && funding[s.symbol] != null ? funding[s.symbol] : null;
    applySentiment(s, { fundingRate, fearGreed });
  }
  return list;
}

ipcMain.handle('market:analyze', async (_e, { symbol, market, interval }) => {
  const m = market || 'SPOT';
  const iv = interval || '1d';
  const blocked = signalsBlocked();
  if (blocked) {
    return {
      symbol, market: m, interval: iv, type: 'HOLD', score: 0, price: 0,
      reason: blockedMessage(blocked), blocked: true, locked: true,
      bollinger: {}, chart: []
    };
  }
  if (m === 'FOREX') {
    try {
      let candles = await platforms.getForexKlines(symbol, 150);
      if (!candles?.length) {
        // last-resort empty guard (getForexKlines should already synth)
        candles = [{ openTime: Date.now(), open: 1, high: 1.01, low: 0.99, close: 1, volume: 1, closeTime: Date.now() }];
      }
      return addHigherTimeframeConfirmation(analyzeSymbol(symbol, candles, m, iv), m, iv, candles);
    } catch (e) {
      console.warn('market:analyze FOREX', e.message || e);
      return {
        symbol,
        market: 'FOREX',
        interval: iv,
        type: 'HOLD',
        score: 0,
        price: 0,
        reason: 'Forex feed temporarily unavailable — try again or Scan Market',
        error: e.message || 'Forex data unavailable',
        bollinger: {},
        chart: []
      };
    }
  }
  const raw = m === 'FUTURES'
    ? await binance.getFuturesKlines(symbol, iv, 1000)
    : await binance.getSpotKlines(symbol, iv, 1000);
  const signal = analyzeSymbol(symbol, parseKlines(raw), m, iv);
  const confirmed = addHigherTimeframeConfirmation(signal, m, iv);
  await enrichSentiment([confirmed], m);
  return confirmed;
});

ipcMain.handle('market:scan', async (_e, { market, interval, limit }) => {
  const m = market || 'SPOT';
  const iv = interval || '1d';
  const max = Math.min(Math.max(limit || 40, 10), 120);

  const blocked = signalsBlocked();
  if (blocked) {
    return {
      results: [],
      bbBuys: [],
      newPairs: [],
      newListings: [],
      upcoming: [],
      candleClose: candleCloseEta(iv),
      scannedAt: new Date().toISOString(),
      blocked: true,
      locked: true,
      tamper: !!blocked.tamper,
      blockReason: blocked.reason,
      message: blockedMessage(blocked)
    };
  }

  if (m === 'FOREX') {
    const ticks = await platforms.getForexTickers();
    const results = [];
    const bbBuys = [];
    for (const t of ticks.slice(0, max)) {
      try {
        const candles = await platforms.getForexKlines(t.symbol, 120);
        if (candles.length < 30) continue;
        const signal = await addHigherTimeframeConfirmation(
          analyzeSymbol(t.symbol, candles, 'FOREX', iv),
          'FOREX',
          iv,
          candles
        );
        signal.volume24h = 0;
        signal.change24h = 0;
        signal.platform = 'FOREX';
        signalLab.noteSignal(signal, 'FOREX', iv);
        const { chart, ...light } = signal;
        results.push(light);
        if (signal.bollinger.touchLower && signal.type !== 'SELL') bbBuys.push(light);
      } catch {}
      await yieldUI();
    }
    const fxResults = results.sort((a, b) => b.score - a.score);
    announceStrongSignals(fxResults, 'FOREX');
    announceBbLower(bbBuys, 'FOREX');
    const fxSessions = autoTradeSessions.filter((s) => s.enabled && s.market === 'FOREX');
    if (!fxSessions.length) {
      const running = autoTradeSessions.filter((s) => s.enabled).map((s) => s.market);
      const fxSignals = fxResults.filter((r) => r.type === 'BUY' || r.type === 'SELL').length;
      emitAutoSkipDiag('FOREX', '—', running.length
        ? `no FOREX session is running (running: ${running.join(', ')})`
        : 'no auto session is running — press ▶ Start on a session', fxSignals);
    }
    for (const sess of fxSessions) {
      await maybeAutoTrade(fxResults.filter((r) => r.type === 'BUY' || r.type === 'SELL'), 'FOREX', sess);
    }
    return {
      results: fxResults,
      bbBuys,
      newPairs: [],
      newListings: [],
      upcoming: [],
      candleClose: candleCloseEta(iv),
      scannedAt: new Date().toISOString(),
      platform: 'FOREX'
    };
  }

  const tickers = m === 'FUTURES' ? await binance.getFuturesTicker24h() : await binance.getSpotTicker24h();
  const asciiOk = allowNonAsciiPairs();
  const top = (Array.isArray(tickers) ? tickers : [])
    .filter((t) => t.symbol.endsWith('USDT')
      && !t.symbol.includes('_')
      && !t.symbol.includes('UP')
      && !t.symbol.includes('DOWN')
      && (asciiOk || isAsciiPairSymbol(t.symbol)))
    .sort((a, b) => +b.quoteVolume - +a.quoteVolume)
    .slice(0, max);

  const results = [];
  const bbBuys = [];
  let done = 0;
  let banned = null;
  for (const t of top) {
    try {
      const raw = m === 'FUTURES'
        ? await binance.getFuturesKlines(t.symbol, iv, 120)
        : await binance.getSpotKlines(t.symbol, iv, 120);
      const signal = await addHigherTimeframeConfirmation(
        analyzeSymbol(t.symbol, parseKlines(raw), m, iv),
        m,
        iv
      );
      signal.volume24h = +t.quoteVolume;
      signal.change24h = +t.priceChangePercent;
      signalLab.noteSignal(signal, m, iv);
      // strip heavy chart from list payload — detail fetch has chart
      const { chart, ...light } = signal;
      results.push(light);
      if (signal.bollinger.touchLower && signal.type !== 'SELL') bbBuys.push(light);
    } catch (e) {
      // A rate-limit ban hits every symbol, so stop instead of adding to it.
      if (e?.binanceBanned) { banned = e; break; }
    }
    done += 1;
    if (done % 5 === 0) {
      mainWindow?.webContents.send('scan:progress', { done, total: top.length, market: m });
    }
    // Yield to the UI thread between symbols so the WebView never freezes
    // long enough to trigger an Android "App isn't responding" dialog.
    await yieldUI();
  }
  if (banned) throw banned;
  mainWindow?.webContents.send('scan:progress', { done: top.length, total: top.length, market: m });

  const pairMeta = await listUsdtPairsWithMeta(m);
  const pairs = pairMeta.map((x) => x.symbol);
  let newPairs = [];
  if (m === 'SPOT') {
    if (knownSpotPairs.length) newPairs = detectNewListings(pairs, knownSpotPairs);
    knownSpotPairs = pairs;
    saveSettings({ knownSpotPairs: pairs });
  } else {
    if (knownFuturesPairs.length) newPairs = detectNewListings(pairs, knownFuturesPairs);
    knownFuturesPairs = pairs;
    saveSettings({ knownFuturesPairs: pairs });
  }

  if (newPairs.length) {
    notifyI18n('n_new_pair', null, { _body: `${m}: ${newPairs.slice(0, 8).join(', ')}` }, true);
  }

  /* ---- Recently-listed coins (with entry + signal) ------------------------
   * Newly listed pairs are usually far outside the top-volume scan, so they are
   * analysed separately here: the exchange listing date, how many days ago, and
   * a full signal (entry / TP / SL / grade) that refreshes on every scan.
   *   FUTURES — exact date from the exchange (`onboardDate`), free.
   *   SPOT    — no exchange date, so the newest symbols (exchangeInfo is in
   *             listing order) are probed once and cached in settings.
   */
  const nowMs = Date.now();
  let recentMeta = [];
  if (m === 'FUTURES') {
    recentMeta = pairMeta
      .filter((x) => x.onboard > 0 && nowMs - x.onboard <= NEW_LISTING_WINDOW_MS)
      .sort((a, b) => b.onboard - a.onboard)
      .slice(0, NEW_LISTINGS_MAX);
  } else {
    const maxRank = pairMeta.reduce((mx, x) => Math.max(mx, x.rank), 0);
    const probe = pairMeta
      .filter((x) => x.rank > maxRank - SPOT_PROBE)
      .sort((a, b) => b.rank - a.rank);
    let discovered = false;
    for (const item of probe) {
      if (spotListingCache[item.symbol]) continue;
      try {
        if (await resolveSpotListingDate(item.symbol)) discovered = true;
      } catch { /* a single missing symbol must not break the scan */ }
    }
    // keep the cache bounded — drop anything well past the window
    for (const sym of Object.keys(spotListingCache)) {
      if (nowMs - spotListingCache[sym] > NEW_LISTING_WINDOW_MS * 2) delete spotListingCache[sym];
    }
    if (discovered) saveSettings({ spotListingCache });
    recentMeta = Object.entries(spotListingCache)
      .map(([symbol, onboard]) => ({ symbol, onboard }))
      .filter((x) => nowMs - x.onboard <= NEW_LISTING_WINDOW_MS)
      .sort((a, b) => b.onboard - a.onboard)
      .slice(0, NEW_LISTINGS_MAX);
  }

  const newListings = [];
  for (const item of recentMeta) {
    try {
      const raw = m === 'FUTURES'
        ? await binance.getFuturesKlines(item.symbol, iv, 120)
        : await binance.getSpotKlines(item.symbol, iv, 120);
      const signal = await addHigherTimeframeConfirmation(
        analyzeSymbol(item.symbol, parseKlines(raw), m, iv),
        m,
        iv
      );
      signal.volume24h = 0;
      signal.change24h = 0;
      const { chart, ...light } = signal;
      newListings.push({
        ...light,
        onboard: item.onboard,
        onboardISO: new Date(item.onboard).toISOString(),
        daysSince: Math.max(0, Math.floor((nowMs - item.onboard) / 86400e3)),
        newlyDetected: newPairs.includes(item.symbol)
      });
    } catch {}
    await yieldUI();
  }

  await enrichSentiment(results, m);
  await enrichSentiment(newListings, m);
  announceStrongSignals(results, m);
  announceBbLower(bbBuys, m);

  const upcoming = await getUpcomingListings(m);

  const activeSessions = autoTradeSessions.filter((s) => s.enabled && (s.market === m || s.market === 'BOTH'));
  if (!activeSessions.length) {
    const running = autoTradeSessions.filter((s) => s.enabled).map((s) => s.market);
    const signals = results.filter((r) => r.type === 'BUY' || r.type === 'SELL').length;
    emitAutoSkipDiag(m, '—', running.length
      ? `no ${m} session is running (running: ${running.join(', ')})`
      : 'no auto session is running — press ▶ Start on a session', signals);
  }
  for (const sess of activeSessions) {
    await maybeAutoTrade(results.filter((r) => r.type === 'BUY' || r.type === 'SELL'), m, sess);
  }

  // Watchlist alerts
  for (const w of watchlist.filter((x) => x.market === m)) {
    const hit = results.find((r) => r.symbol === w.symbol);
    if (hit && (hit.type === 'BUY' || hit.bollinger?.touchLower)) {
      notifyI18n('n_watch', 'n_watch_body', { symbol: w.symbol, type: hit.type, score: hit.score }, true);
    }
  }

  return {
    results: results.sort((a, b) => (GRADE_RANK[b.grade] || 0) - (GRADE_RANK[a.grade] || 0) || b.score - a.score),
    bbBuys,
    newPairs,
    newListings,
    upcoming,
    candleClose: candleCloseEta(iv),
    scannedAt: new Date().toISOString()
  };
});

/* ---- Multi-timeframe scan -----------------------------------------------
 * Additive to `market:scan` — the single-timeframe path above is untouched.
 * The same top-volume list is analysed on several timeframes at once and each
 * row reports one signal per timeframe plus a confluence summary, so all the
 * charts are read side by side instead of one bar at a time.
 *
 * One symbol now costs one klines request per timeframe, so the list is capped
 * to stay quick on mobile (and well inside the exchange rate limit).
 */
const MULTI_TF_DEFAULT = ['3m', '15m', '1h', '4h', '1d'];
const MULTI_TF_MAX_SYMBOLS = 20;

ipcMain.handle('market:scanMultiTf', async (_e, { market, limit, timeframes } = {}) => {
  const m = market || 'SPOT';
  const tfs = (Array.isArray(timeframes) && timeframes.length ? timeframes : MULTI_TF_DEFAULT)
    .filter((iv) => MULTI_TF_DEFAULT.includes(iv));
  const max = Math.min(Math.max(limit || MULTI_TF_MAX_SYMBOLS, 1), MULTI_TF_MAX_SYMBOLS);

  // The Forex feed is daily-only, so a multi-timeframe read is not available.
  if (m === 'FOREX') {
    return {
      results: [],
      timeframes: tfs,
      unsupported: true,
      scannedAt: new Date().toISOString(),
      platform: 'FOREX'
    };
  }

  const tickers = m === 'FUTURES' ? await binance.getFuturesTicker24h() : await binance.getSpotTicker24h();
  const asciiOk = allowNonAsciiPairs();
  const top = (Array.isArray(tickers) ? tickers : [])
    .filter((t) => t.symbol.endsWith('USDT')
      && !t.symbol.includes('_')
      && !t.symbol.includes('UP')
      && !t.symbol.includes('DOWN')
      && (asciiOk || isAsciiPairSymbol(t.symbol)))
    .sort((a, b) => +b.quoteVolume - +a.quoteVolume)
    .slice(0, max);

  const results = [];
  let done = 0;
  let banned = null;
  for (const t of top) {
    try {
      const frames = {};
      let price = 0;
      for (const iv of tfs) {
        const raw = m === 'FUTURES'
          ? await binance.getFuturesKlines(t.symbol, iv, 120)
          : await binance.getSpotKlines(t.symbol, iv, 120);
        const sig = analyzeSymbol(t.symbol, parseKlines(raw), m, iv);
        frames[iv] = { type: sig.type, score: sig.score, grade: sig.grade };
        if (sig.price) price = sig.price;
        // Yield between every request so the WebView never freezes long
        // enough to trigger an Android "App isn't responding" dialog.
        await yieldUI();
      }
      const list = tfs.map((iv) => frames[iv]);
      const buys = list.filter((f) => f.type === 'BUY').length;
      const sells = list.filter((f) => f.type === 'SELL').length;
      const strongest = list.slice().sort((a, b) => (GRADE_RANK[b.grade] || 0) - (GRADE_RANK[a.grade] || 0))[0];
      const dir = buys > sells ? 'BUY' : sells > buys ? 'SELL' : 'HOLD';
      const aligned = Math.max(buys, sells);
      results.push({
        symbol: t.symbol,
        market: m,
        price,
        volume24h: +t.quoteVolume,
        change24h: +t.priceChangePercent,
        frames,
        confluence: {
          buys,
          sells,
          holds: list.length - buys - sells,
          total: list.length,
          dir,
          aligned,
          label: `${aligned}/${list.length} ${dir}`,
          strongestGrade: strongest?.grade || ''
        }
      });
    } catch (e) {
      // A rate-limit ban hits every symbol, so stop instead of adding to it.
      if (e?.binanceBanned) { banned = e; break; }
    }
    done += 1;
    mainWindow?.webContents.send('scan:progress', { done, total: top.length, market: m, multiTf: true });
    await yieldUI();
  }
  if (banned) throw banned;
  mainWindow?.webContents.send('scan:progress', { done: top.length, total: top.length, market: m, multiTf: true });

  // Most frames agreeing first, then the strongest grade, then score.
  results.sort((a, b) => (b.confluence.aligned - a.confluence.aligned)
    || ((GRADE_RANK[b.confluence.strongestGrade] || 0) - (GRADE_RANK[a.confluence.strongestGrade] || 0)));

  return { results, timeframes: tfs, scannedAt: new Date().toISOString(), platform: m };
});

/* ---- Scalp scan (15m) ---------------------------------------------------
 * Additive to `market:scan` — the single-timeframe path above is untouched.
 * Reads every pair on the 15-minute chart only and keeps the strongest quick
 * in/out setups: the base read must be STRONG, so only genuinely tradeable
 * scalps reach the table. TP/SL are ATR-based (tight) rather than the wider
 * swing levels the main scan uses. Crypto reads Binance 15m; Forex reads real
 * Yahoo 15m bars.
 */
const SCALP_TF = '15m';
const SCALP_MAX_SYMBOLS = 20;
// Tight ATR scalp template — stop 1×ATR, first target 1.5×ATR, runner 2.5×ATR.
// Works the same on 15m crypto and 15m forex (ATR scales with each market).
const SCALP_SL_ATR = 1;
const SCALP_TP1_ATR = 1.5;
const SCALP_TP2_ATR = 2.5;

function scalpLevels(sig) {
  const entry = +sig.price;
  const atr = +sig.atr;
  if (!Number.isFinite(entry) || entry <= 0 || !Number.isFinite(atr) || atr <= 0) return null;
  const dir = sig.type === 'BUY' ? 1 : -1;
  return {
    sl: entry - dir * atr * SCALP_SL_ATR,
    tp1: entry + dir * atr * SCALP_TP1_ATR,
    tp2: entry + dir * atr * SCALP_TP2_ATR,
    rr: SCALP_TP1_ATR / SCALP_SL_ATR,
    atrPct: (atr / entry) * 100
  };
}

function scalpRow(sig, extra = {}) {
  // Only STRONG reads count — a scalp desk that lists everything is worthless.
  if (sig.grade !== 'STRONG') return null;
  if (sig.type !== 'BUY' && sig.type !== 'SELL') return null;
  const lv = scalpLevels(sig);
  if (!lv) return null;
  return {
    symbol: sig.symbol,
    market: sig.market,
    price: sig.price,
    type: sig.type,
    grade: sig.grade,
    score: sig.score,
    entry: +sig.price,
    entryType: sig.entryType || 'MARKET',
    tp1: +lv.tp1.toFixed(8),
    tp2: +lv.tp2.toFixed(8),
    sl: +lv.sl.toFixed(8),
    rr: +lv.rr.toFixed(2),
    atrPct: +lv.atrPct.toFixed(2),
    trend: sig.context?.trend || 'SIDE',
    candle: sig.candle?.name || '',
    reason: (sig.reasons || [])[0] || '',
    ...extra
  };
}

ipcMain.handle('market:scanScalp', async (_e, { market, limit } = {}) => {
  const m = market || 'SPOT';
  const max = Math.min(Math.max(limit || SCALP_MAX_SYMBOLS, 1), SCALP_MAX_SYMBOLS);
  const results = [];
  let done = 0;
  let total = 0;

  const blocked = signalsBlocked();
  if (blocked) {
    return {
      results: [],
      blocked: true,
      locked: true,
      tamper: !!blocked.tamper,
      message: blockedMessage(blocked),
      timeframe: SCALP_TF,
      scannedAt: new Date().toISOString(),
      platform: m
    };
  }

  if (m === 'FOREX') {
    // Real 15m bars from Yahoo Finance — the daily Frankfurter feed cannot scalp.
    const pairs = platforms.FOREX_PAIRS;
    total = pairs.length;
    for (const sym of pairs) {
      try {
        const candles = await platforms.getForexIntradayKlines(sym, SCALP_TF, 200);
        if (candles.length >= 60) {
          const sig = analyzeSymbol(sym, candles, 'FOREX', SCALP_TF);
          sig.platform = 'FOREX';
          const row = scalpRow(sig, { volume24h: 0, change24h: 0, platform: 'FOREX' });
          if (row) results.push(row);
        }
      } catch { /* a pair the intraday feed refused — skip it */ }
      done += 1;
      mainWindow?.webContents.send('scan:progress', { done, total, market: m, scalp: true });
      await yieldUI();
    }
  } else {
    const tickers = m === 'FUTURES' ? await binance.getFuturesTicker24h() : await binance.getSpotTicker24h();
    const asciiOk = allowNonAsciiPairs();
    const top = (Array.isArray(tickers) ? tickers : [])
      .filter((t) => t.symbol.endsWith('USDT')
        && !t.symbol.includes('_')
        && !t.symbol.includes('UP')
        && !t.symbol.includes('DOWN')
        && (asciiOk || isAsciiPairSymbol(t.symbol)))
      .sort((a, b) => +b.quoteVolume - +a.quoteVolume)
      .slice(0, max);
    total = top.length;
    let banned = null;
    for (const t of top) {
      try {
        const raw = m === 'FUTURES'
          ? await binance.getFuturesKlines(t.symbol, SCALP_TF, 200)
          : await binance.getSpotKlines(t.symbol, SCALP_TF, 200);
        const candles = parseKlines(raw).filter((c) => c.closeTime < Date.now());
        if (candles.length >= 60) {
          const sig = analyzeSymbol(t.symbol, candles, m, SCALP_TF);
          const row = scalpRow(sig, { volume24h: +t.quoteVolume, change24h: +t.priceChangePercent });
          if (row) results.push(row);
        }
      } catch (e) {
        // A rate-limit ban hits every symbol, so stop instead of adding to it.
        if (e?.binanceBanned) { banned = e; break; }
      }
      done += 1;
      mainWindow?.webContents.send('scan:progress', { done, total, market: m, scalp: true });
      await yieldUI();
    }
    if (banned) throw banned;
  }

  // Best reward/risk first, then the strongest grade, then score.
  results.sort((a, b) => (b.rr - a.rr)
    || ((GRADE_RANK[b.grade] || 0) - (GRADE_RANK[a.grade] || 0))
    || b.score - a.score);

  return { results, timeframe: SCALP_TF, scannedAt: new Date().toISOString(), platform: m };
});

let moneyStopDay = '';

function moneyEquity() {
  let eq = 1000;
  for (const j of journal) {
    const qty = +j.qty || 0;
    const entry = +j.entry || 0;
    const pct = +j.pnlPct || 0;
    if (qty > 0 && entry > 0 && Number.isFinite(pct)) eq += (pct / 100) * entry * qty;
  }
  if (!Number.isFinite(eq) || eq < 100) return 100;
  return eq;
}

function todayPnlUsd() {
  const day = new Date().toISOString().slice(0, 10);
  let pnl = 0;
  for (const j of journal) {
    if (!String(j.at || '').startsWith(day)) continue;
    const qty = +j.qty || 0;
    const entry = +j.entry || 0;
    const pct = +j.pnlPct || 0;
    if (qty > 0 && entry > 0) pnl += (pct / 100) * entry * qty;
  }
  return pnl;
}

/** Fixed 1% risk. Size comes from the stop. Returns null when a valid size cannot be used. */
function planSize({ equity, entry, sl, market, leverage }) {
  const e = +entry;
  const s = +sl;
  if (!e || !s || e === s) return null;
  const dist = Math.abs(e - s) / e;
  if (dist < 0.003 || dist > 0.15) return null;
  const risk = Math.max(100, +equity || 1000) * 0.01;
  const notional = Math.min(Math.max(100, +equity || 1000), risk / dist);
  const stopPct = +(dist * 100).toFixed(2);
  if (market === 'FOREX') {
    const lots = Math.floor((notional / 100000) * 100) / 100;
    if (lots < 0.01) return null;
    return { quote: notional, lots, riskUsd: +risk.toFixed(2), stopPct };
  }
  if (market === 'FUTURES') {
    const lev = Math.max(1, +leverage || 1);
    const margin = notional / lev;
    if (margin < 1) return null;
    return { quote: +margin.toFixed(2), lots: null, riskUsd: +risk.toFixed(2), stopPct };
  }
  if (notional < 11) return null;
  return { quote: +notional.toFixed(2), lots: null, riskUsd: +risk.toFixed(2), stopPct };
}

function moneyBlockedToday() {
  const eq = moneyEquity();
  if (todayPnlUsd() > -eq * 0.02) return false;
  const day = new Date().toISOString().slice(0, 10);
  if (moneyStopDay !== day) {
    moneyStopDay = day;
    notify('Money management', 'Daily loss is about 2%. No new auto trades until tomorrow.', true);
  }
  return true;
}

/* -------------------------------------------------------------------------
 * Martingale ladder engine (additive, opt-in, OFF by default).
 * Driven by the monitor loop so it also works for hand-placed (manual) trades.
 * Rule: after an adverse move of step × rung % AND a fresh same-side signal,
 * add one more order sized base × mult^rung. Hard-capped by martMaxAdds and the
 * total ladder risk (martRiskCapPct of equity). The root trade drives the adds.
 * ----------------------------------------------------------------------- */
const martInFlight = new Set();

function martQuoteOf(t) {
  const qty = +(t.qty || 0);
  const entry = +(t.entry || 0);
  return +(t.martBaseQuote || (qty * entry) || 0);
}

/** Notional exposure of one trade in USD (used by the ladder risk cap). */
function tradeNotionalUsd(t, px) {
  const market = t.market || 'SPOT';
  const price = +(px || t.entry || 0);
  if (market === 'FOREX') {
    const lots = +(t.forexLots || 0);
    if (lots > 0) return lots * 100000;
    return +(t.qty || 0) * price;
  }
  if (market === 'FUTURES') {
    const lev = Math.max(1, +t.leverage || 1);
    return +(t.qty || 0) * price * lev;
  }
  return +(t.qty || 0) * price;
}

/** USD risked if this trade's stop is hit (falls back to ~2% of notional). */
function tradeRiskUsd(t, px) {
  const notional = tradeNotionalUsd(t, px);
  const entry = +(t.entry || 0);
  const sl = +t.sl;
  let pct = 2;
  if (entry > 0 && sl > 0) pct = (Math.abs(entry - sl) / entry) * 100;
  return notional * (pct / 100);
}

/** Re-read the market for a trade's pair and return a fresh signal (or null). */
async function refreshSignalForTrade(t) {
  const m = t.market || 'SPOT';
  const iv = t.interval || '1d';
  try {
    if (m === 'FOREX') {
      const candles = await platforms.getForexKlines(t.symbol, 120);
      if (!candles || candles.length < 30) return null;
      return analyzeSymbol(t.symbol, candles, 'FOREX', iv);
    }
    const raw = m === 'FUTURES'
      ? await binance.getFuturesKlines(t.symbol, iv, 200)
      : await binance.getSpotKlines(t.symbol, iv, 200);
    const signal = analyzeSymbol(t.symbol, parseKlines(raw), m, iv);
    return addHigherTimeframeConfirmation(signal, m, iv);
  } catch {
    return null;
  }
}

/**
 * Try to add one martingale rung to the ladder rooted at `t` (root only).
 * Returns true when an add order was placed.
 */
async function maybeMartingaleAdd(t, price) {
  if (!t || t.status !== 'OPEN' || !t.martEnabled || t.martRoot) return false;
  if (!price || !t.id) return false;
  if (martInFlight.has(t.id)) return false;

  const market = t.market || 'SPOT';
  const long = (t.side || 'BUY') === 'BUY';
  const step = Math.max(0.2, Math.min(20, +(t.martStepPct != null ? t.martStepPct : autoTradeConfig.martStepPct) || 1));
  const mult = Math.max(1, Math.min(4, +(t.martMult != null ? t.martMult : autoTradeConfig.martMult) || 2));
  const maxAdds = Math.max(0, Math.min(6, Math.round(t.martMaxAdds != null ? +t.martMaxAdds : autoTradeConfig.martMaxAdds)));
  const capPct = Math.max(0.5, Math.min(50, +(t.martRiskCapPct != null ? t.martRiskCapPct : autoTradeConfig.martRiskCapPct) || 5));
  if (maxAdds <= 0) return false;

  const ladder = openTrades.filter((x) => x.status === 'OPEN' && (x.martRoot || x.id) === t.id);
  const adds = Math.max(0, ladder.length - 1);
  if (adds >= maxAdds) return false;

  // Respect the per-session max-open count (ladder rungs count as open trades).
  if (t.sessionId) {
    const session = autoTradeSessions.find((s) => s.id === t.sessionId);
    const heatCap = session ? (session.moneyMgmt ? Math.min(3, +session.maxOrders || 3) : +session.maxOrders || 3) : 3;
    const sessionOpen = openTrades.filter((x) => x.status === 'OPEN' && x.sessionId === t.sessionId);
    if (sessionOpen.length >= heatCap) return false;
  }

  // 1) Adverse move gate — cheap, no network call yet.
  const entry = +t.entry;
  if (!entry) return false;
  const adversePct = long ? ((entry - price) / entry) * 100 : ((price - entry) / entry) * 100;
  const required = step * (adds + 1);
  if (adversePct < required) return false;

  martInFlight.add(t.id);
  try {
    // 2) A fresh same-side signal must still stand — re-read the market.
    const sig = await refreshSignalForTrade(t);
    const sigSide = sig && (sig.type === 'SELL' ? 'SELL' : sig.type === 'BUY' ? 'BUY' : '');
    if (!sig || sigSide !== (t.side || 'BUY') || sig.grade === 'NONE') return false;

    const level = adds + 1;
    const rungQuote = martQuoteOf(t) * Math.pow(mult, level);
    if (!(rungQuote > 0)) return false;

    // 3) Hard cap: the whole ladder's risk must stay under capPct of equity.
    const capUsd = moneyEquity() * (capPct / 100);
    const existingRisk = ladder.reduce((a, x) => a + tradeRiskUsd(x, price), 0);
    const rungStopPct = (Math.abs(price - (+t.sl || price)) / price) * 100 || 2;
    const rungNotional = rungQuote * (market === 'FUTURES' ? Math.max(1, +t.leverage || 1) : 1);
    const rungRisk = rungNotional * (rungStopPct / 100);
    const qty = estimateQty(price, rungQuote);
    if (!qty || existingRisk + rungRisk > capUsd) {
      notifyI18n('n_mart_cap', 'n_mart_cap_body', { symbol: t.symbol, cap: capPct }, false);
      return false;
    }

    // Place the add: live only when the parent is live and the platform can trade.
    let order = { orderId: `mart-${Date.now()}` };
    const liveOk = !t.paper
      && t.platform !== 'FOREX_DEMO'
      && exchanges.supportsLiveOrders(t.platform)
      && exchanges.hasRequiredCreds(t.platform, getRawKeys(t.platform));
    if (liveOk) {
      try {
        order = await exchanges.placeOrder(t.platform, getRawKeys(t.platform), {
          market,
          symbol: t.symbol,
          side: t.side || 'BUY',
          quantity: qty,
          type: 'MARKET',
          leverage: Math.max(1, +t.leverage || 1),
          marginType: t.marginType || 'CROSSED',
          forexLots: t.forexLots,
          stopLoss: market === 'FOREX' ? (sig.sl || t.sl) : undefined
        });
        if (!order?.orderId) order.orderId = order?.ordId || order?.id || `mart-${Date.now()}`;
      } catch (e) {
        notifyI18n('n_auto_err', null, { _body: `${t.symbol} martingale add: ${e.message || e}` }, true);
        return false;
      }
    }

    const child = {
      symbol: t.symbol,
      market,
      platform: t.platform,
      sessionId: t.sessionId,
      side: t.side || 'BUY',
      entry: price,
      tp1: sig.tp1 != null ? sig.tp1 : t.tp1,
      tp2: sig.tp2 != null ? sig.tp2 : t.tp2,
      sl: sig.sl != null ? sig.sl : t.sl,
      bbLower: sig.bollinger?.lower != null ? +sig.bollinger.lower : (t.bbLower != null ? t.bbLower : null),
      bbMid: sig.bollinger?.mid != null ? +sig.bollinger.mid : (t.bbMid != null ? t.bbMid : null),
      bbUpper: sig.bollinger?.upper != null ? +sig.bollinger.upper : (t.bbUpper != null ? t.bbUpper : null),
      bandExtended: false,
      qty,
      leverage: market === 'FUTURES' ? Math.max(1, +t.leverage || 1) : 1,
      marginType: market === 'FUTURES' ? (t.marginType || 'CROSSED') : undefined,
      forexLots: t.forexLots,
      orderId: order.orderId,
      at: new Date().toISOString(),
      reasons: [`Martingale rung ${level} — adverse ${adversePct.toFixed(2)}% + same-side ${sigSide} signal`],
      fromSignal: true,
      signalType: t.side || 'BUY',
      signalGrade: sig.grade,
      auto: !!t.auto,
      autoClose: true,
      paper: !liveOk,
      martEnabled: true,
      martRoot: t.id,
      martLevel: level,
      martStepPct: step,
      martMult: mult,
      martMaxAdds: maxAdds,
      martRiskCapPct: capPct,
      trailArmPct: t.trailArmPct != null ? t.trailArmPct : autoTradeConfig.trailArmPct,
      trailPct: t.trailPct != null ? t.trailPct : autoTradeConfig.trailPct,
      trailingStop: t.trailingStop,
      tp1Pct: t.tp1Pct,
      tp2Pct: t.tp2Pct
    };
    trackTrade(child);
    notifyI18n('n_mart_open', 'n_mart_open_body', {
      symbol: t.symbol, rung: level, qty, price, move: adversePct.toFixed(2)
    }, true);
    mainWindow?.webContents.send('auto-trade', child);
    return true;
  } finally {
    martInFlight.delete(t.id);
  }
}

/** Explain in the UI why a scan produced no auto trade (always sent, even on early exit). */
function emitAutoSkipDiag(market, platform, message, signalCount = 0) {
  mainWindow?.webContents.send('auto:diagnostic', {
    market,
    platform: platform || '—',
    paper: null,
    // Report the real BUY/SELL count from this scan — never a bare 0, which
    // wrongly suggests the scan itself found nothing.
    total: signalCount,
    sideOk: 0,
    gradeOk: 0,
    qualityOk: 0,
    onBandOk: 0,
    candidates: 0,
    reasons: {},
    skip: message
  });
}

async function maybeAutoTrade(buys, market, session) {
  if (!session) return;
  const cfg = session;
  const platform = cfg.platform || 'BINANCE';

  // Skip a session whose platform cannot trade this market (defensive guard)
  const sMeta = platforms.getPlatform(platform);
  if (sMeta && market && !(sMeta.markets || []).includes(market)) {
    return emitAutoSkipDiag(market, platform, `${platform} cannot trade ${market}`);
  }

  // Live execution: DEMO/paper unless this session has usable keys for its platform.
  // The global DEMO switch (autoTradeConfig.forcePaper) mirrors the UI DEMO/LIVE toggle
  // and is the single source of truth — the per-session forcePaper is only the value
  // captured when the session was saved and must NOT override a later switch to LIVE.
  const creds = getRawKeys(platform);
  const canLive = !autoTradeConfig.forcePaper
    && platform !== 'FOREX_DEMO'
    && exchanges.supportsLiveOrders(platform)
    && exchanges.hasRequiredCreds(platform, creds);

  // Count only this session's own open trades (legacy trades fall back to platform+market)
  const sessionOpen = openTrades.filter((t) => t.status === 'OPEN'
    && (t.sessionId ? t.sessionId === cfg.id : (t.platform === platform && t.market === market)));
  const heatCap = cfg.moneyMgmt ? Math.min(3, +cfg.maxOrders || 3) : +cfg.maxOrders;
  if (sessionOpen.length >= heatCap) {
    return emitAutoSkipDiag(market, platform, `max open reached (${sessionOpen.length}/${heatCap}) — no new trade this scan`);
  }
  if (cfg.moneyMgmt && moneyBlockedToday()) {
    return emitAutoSkipDiag(market, platform, 'daily loss cap (~-2%) reached — no new auto trades today');
  }

  const minSpot = 11;
  const minFut = 1;
  let quote = market === 'FUTURES'
    ? Math.max(minFut, +cfg.futuresQuote || 1)
    : Math.max(minSpot, +cfg.quoteAmount || 11);

  const allowStrong = cfg.autoStrong !== false;
  const allowCaution = !!cfg.autoCaution;
  const allowHigherStrong = !!cfg.autoHigherStrong;
  const gradeAllowed = (grade) =>
    (grade === 'HIGHER STRONG' && allowHigherStrong)
    || (grade === 'STRONG' && allowStrong)
    || (grade === 'CAUTION' && allowCaution);

  // Explain *why* a session is in paper mode (shown in the UI diagnostics box).
  let paperWhy = '';
  if (!canLive) {
    if (autoTradeConfig.forcePaper) paperWhy = 'DEMO mode is ON — switch the top DEMO/LIVE toggle to LIVE';
    else if (platform === 'FOREX_DEMO') paperWhy = 'Forex Demo platform — paper only';
    else if (!exchanges.supportsLiveOrders(platform)) paperWhy = `${platform} has no live connector — paper only`;
    else if (!exchanges.hasRequiredCreds(platform, creds)) paperWhy = `no API key saved for ${platform} — add it in the API Keys tab`;
    else paperWhy = 'paper mode';
  }

  // Diagnostic counters — explain why signals are rejected so the user can tune.
  const diag = {
    market,
    platform,
    sessionId: cfg.id,
    canLive,
    paper: !canLive,
    paperWhy,
    total: buys.length,
    sideOk: 0,
    gradeOk: 0,
    qualityOk: 0,
    onBandOk: 0,
    candidates: 0,
    reasons: {}
  };
  for (const b of buys) {
    const sideOk = b.type === 'BUY' || ((market === 'FUTURES' || market === 'FOREX') && b.type === 'SELL');
    if (!sideOk) continue;
    diag.sideOk += 1;

    const gradeOk = gradeAllowed(b.grade);
    if (!gradeOk) {
      const r = `grade_${b.grade || 'NONE'}`;
      diag.reasons[r] = (diag.reasons[r] || 0) + 1;
      continue;
    }
    diag.gradeOk += 1;

    const qi = signalQualityIssue(b, market);
    if (qi) {
      const r = `quality:${qi}`;
      diag.reasons[r] = (diag.reasons[r] || 0) + 1;
      continue;
    }
    diag.qualityOk += 1;

    if (!onBand(b)) {
      const r = 'not_on_band';
      diag.reasons[r] = (diag.reasons[r] || 0) + 1;
      continue;
    }
    diag.onBandOk += 1;
  }

  const candidates = buys
    .filter((b) => {
      const sideOk = b.type === 'BUY' || ((market === 'FUTURES' || market === 'FOREX') && b.type === 'SELL');
      const gradeOk = gradeAllowed(b.grade);
      return sideOk && gradeOk && !signalQualityIssue(b, market) && onBand(b);
    })
    .slice(0, heatCap - sessionOpen.length);

  diag.candidates = candidates.length;
  diag.opened = 0;
  diag.orderSkip = {};

  for (const sig of candidates) {
    if (openTrades.find((t) => t.symbol === sig.symbol && t.status === 'OPEN')) {
      diag.orderSkip.already_open = (diag.orderSkip.already_open || 0) + 1;
      continue;
    }
    try {
      let plan = null;
      if (cfg.moneyMgmt) {
        plan = planSize({
          equity: moneyEquity(),
          entry: sig.entry || sig.price,
          sl: sig.sl,
          market,
          leverage: cfg.leverage
        });
        if (!plan) {
          diag.orderSkip.money_risk_cap = (diag.orderSkip.money_risk_cap || 0) + 1;
          continue;
        }
        quote = plan.quote;
      }
      const qty = estimateQty(sig.price, quote);
      if (!qty) {
        diag.orderSkip.quote_too_low = (diag.orderSkip.quote_too_low || 0) + 1;
        continue;
      }
      let order = { orderId: `auto-${Date.now()}` };
      const leverage = Math.min(125, Math.max(1, +cfg.leverage || 5));
      const side = sig.type === 'SELL' ? 'SELL' : 'BUY';
      const bb = sig.bollinger || {};
      const entryPx = +sig.entry || +sig.price;
      let tp1 = sig.tp1;
      let tp2 = sig.tp2;
      if (side === 'BUY') {
        if (+bb.mid > entryPx) tp1 = +bb.mid;
        if (+bb.upper > entryPx) tp2 = +bb.upper;
      } else {
        if (+bb.mid > 0 && +bb.mid < entryPx) tp1 = +bb.mid;
        if (+bb.lower > 0 && +bb.lower < entryPx) tp2 = +bb.lower;
      }

      const margin = String(cfg.marginType || 'CROSSED').toUpperCase() === 'ISOLATED' ? 'ISOLATED' : 'CROSSED';
      if (canLive) {
        try {
          order = await exchanges.placeOrder(platform, creds, {
            market,
            symbol: sig.symbol,
            side,
            quantity: qty,
            type: 'MARKET',
            leverage,
            marginType: margin,
            forexLots: cfg.forexLots,
            stopLoss: market === 'FOREX' ? sig.sl : undefined
          });
          if (!order?.orderId) order.orderId = order?.ordId || order?.id || `live-${Date.now()}`;
        } catch (err) {
          diag.orderSkip.live_order_failed = (diag.orderSkip.live_order_failed || 0) + 1;
          notifyI18n('n_auto_err', null, { _body: `${sig.symbol} (${platform}): ${err.message || err}` }, true);
          continue; // do not track a trade whose live order failed
        }
      }

      const trade = {
        symbol: sig.symbol,
        market,
        platform,
        sessionId: cfg.id,
        side,
        entry: sig.entry,
        tp1,
        tp2,
        sl: sig.sl,
        bbLower: bb.lower != null ? +bb.lower : null,
        bbMid: bb.mid != null ? +bb.mid : null,
        bbUpper: bb.upper != null ? +bb.upper : null,
        bandExtended: false,
        qty,
        leverage: market === 'FUTURES' ? leverage : 1,
        marginType: market === 'FUTURES' ? margin : undefined,
        forexLots: cfg.forexLots,
        orderId: order.orderId,
        at: new Date().toISOString(),
        reasons: sig.reasons,
        fromSignal: true,
        signalType: side,
        signalScore: sig.score,
        signalEntry: sig.entry,
        signalGrade: sig.grade === 'CAUTION' ? 'CAUTION' : sig.grade === 'HIGHER STRONG' ? 'HIGHER STRONG' : 'STRONG',
        trailArmPct: sig.grade === 'CAUTION' ? 0.45 : 0.8,
        auto: true,
        autoClose: true,
        moneyMgmt: !!plan,
        riskUsd: plan ? plan.riskUsd : null,
        stopPct: plan ? plan.stopPct : null,
        trailingStop: !!cfg.trailingStop,
        trailPct: sig.grade === 'CAUTION' ? 0.8 : 1.6,
        // Martingale ladder (opt-in): the monitor loop adds rungs on an adverse
        // move + a fresh same-side signal, capped by count and total ladder risk.
        martEnabled: !!cfg.martingale,
        martLevel: 0,
        martBaseQuote: quote,
        martStepPct: cfg.martStepPct,
        martMult: cfg.martMult,
        martMaxAdds: cfg.martMaxAdds,
        martRiskCapPct: cfg.martRiskCapPct,
        paper: !canLive
      };
      trackTrade(trade);
      diag.opened += 1;
      notifyI18n('n_auto_open', 'n_auto_open_body', { symbol: sig.symbol, qty, lev: market === 'FUTURES' ? ` x${leverage}` : '' }, true);
      mainWindow?.webContents.send('auto-trade', trade);
    } catch (err) {
      diag.orderSkip.error = (diag.orderSkip.error || 0) + 1;
      notifyI18n('n_auto_err', null, { _body: `${sig.symbol}: ${err.message || err}` }, true);
    }
  }

  // Final diagnostic: filter funnel plus how many orders actually opened.
  mainWindow?.webContents.send('auto:diagnostic', diag);
}

function estimateQty(price, quoteAmount) {
  if (!price || price <= 0) return null;
  const raw = quoteAmount / price;
  if (raw >= 1) return Math.floor(raw * 1000) / 1000;
  if (raw >= 0.01) return Math.floor(raw * 10000) / 10000;
  return Math.floor(raw * 1e6) / 1e6;
}

ipcMain.handle('platforms:list', () => platforms.listPlatforms());

ipcMain.handle('trade:manual', async (_e, payload) => {
  const {
    market, symbol, side, quantity, type, price, takeProfit, stopLoss, takeProfit2,
    track, platform = 'BINANCE', leverage = 5, quoteUsdt, tp1Pct, tp2Pct, paper,
    trailingStop, trailPct, marginType = 'CROSSED', forexLots, moneyMgmt,
    fromSignal, signalType, signalScore, signalEntry, signalGrade, trailArmPct,
    bbLower, bbMid, bbUpper,
    martingale, martStepPct, martMult, martMaxAdds, martRiskCapPct
  } = payload;

  let qty = quantity;
  let quoteAmt = quoteUsdt;
  let lots = forexLots;
  let plan = null;
  if (moneyMgmt) {
    plan = planSize({
      equity: moneyEquity(),
      entry: price,
      sl: stopLoss,
      market,
      leverage
    });
    if (!plan) {
      throw new Error('Money management skipped this trade. A valid stop is required, and the exchange minimum must not risk more than about 1%.');
    }
    quoteAmt = plan.quote;
    if (plan.lots) lots = plan.lots;
    qty = null;
  }
  if ((!qty || +qty <= 0) && quoteAmt && price) {
    qty = estimateQty(+price, +quoteAmt);
  }
  if ((!qty || +qty <= 0) && quoteAmt) {
    try {
      const px = market === 'FUTURES'
        ? await binance.getFuturesPrice(symbol)
        : market === 'FOREX'
          ? { price: (await platforms.getForexTickers()).find((x) => x.symbol === symbol)?.price }
          : await binance.getSpotPrice(symbol);
      qty = estimateQty(+px.price, +quoteAmt);
    } catch {}
  }
  if (!qty) throw new Error('Quantity or USDT amount required');

  // Enforce mins
  if (market === 'SPOT' && quoteAmt && +quoteAmt < 11) throw new Error('Spot minimum is 11 USDT');
  if (market === 'FUTURES' && quoteAmt && +quoteAmt < 1) throw new Error('Futures minimum is 1 USDT');

  let order = { orderId: `manual-${Date.now()}` };
  const plat = platforms.getPlatform(platform);
  if (plat && market && !(plat.markets || []).includes(market)) {
    throw new Error(`${plat.name || platform} supports ${(plat.markets || []).join('/')} only — ${market} is not available for this platform.`);
  }
  const isForexPlat = plat?.type === 'FOREX' || market === 'FOREX' || String(platform).startsWith('FOREX');
  const creds = getRawKeys(platform);
  const canLive = platform !== 'FOREX_DEMO'
    && exchanges.supportsLiveOrders(platform)
    && exchanges.hasRequiredCreds(platform, creds);
  const isPaper = !!paper || platform === 'FOREX_DEMO' || !canLive;
  if (isPaper && fromSignal) {
    const qualityIssue = signalQualityIssue({
      type: signalType || side,
      grade: signalGrade,
      score: signalScore,
      entry: signalEntry || price,
      tp1: takeProfit,
      tp2: takeProfit2,
      sl: stopLoss
    }, market);
    if (qualityIssue) {
      throw new Error(`Demo signal skipped: ${qualityIssue}. Use a stronger setup or place a manual practice trade without attaching a signal.`);
    }
  }
  const lev = Math.min(125, Math.max(1, +leverage || 5));
  const margin = String(marginType || 'CROSSED').toUpperCase() === 'ISOLATED' ? 'ISOLATED' : 'CROSSED';

  // A LIMIT order is only a LIMIT order if it carries a price. Without one we
  // must not silently fall back to MARKET — that is how a "limit" trade ends up
  // filling instantly at the market price.
  const orderTypeReq = String(type || 'MARKET').toUpperCase();
  const limitPrice = price != null && String(price).trim() !== '' ? +price : NaN;
  if (orderTypeReq === 'LIMIT' && !(limitPrice > 0)) {
    throw new Error('A LIMIT order needs a limit price. Enter the price you want to buy/sell at, or switch the order type to MARKET.');
  }
  const orderPrice = orderTypeReq === 'LIMIT' ? limitPrice : price;

  if (!isPaper) {
    try {
      order = await exchanges.placeOrder(platform, creds, {
        market,
        symbol,
        side,
        quantity: qty,
        type: orderTypeReq,
        price: orderPrice,
        leverage: lev,
        marginType: margin,
        forexLots: lots,
        stopLoss: isForexPlat ? stopLoss : undefined,
        takeProfit: isForexPlat ? takeProfit : undefined
      });
      if (!order.orderId) order.orderId = order.ordId || order.id || `live-${Date.now()}`;
    } catch (e) {
      throw new Error(e.message || String(e));
    }
  }

  let entry = orderPrice ? +orderPrice : undefined;
  try {
    entry = entry || (await getLastPrice({ symbol, market, platform }));
  } catch {}

  // A LIMIT order the exchange accepted but has not filled yet is an *order*,
  // not an open position. Track it as PENDING so the Positions view can show it,
  // and let the monitor promote it to OPEN (with the real fill price) once filled.
  // DEMO/paper limit orders wait too — the monitor fills them when price crosses.
  const orderType = orderTypeReq;
  const filledQty = order && order.executedQty != null ? +order.executedQty : null;
  const canTrackPending = isPaper || exchanges.supportsOrderLookup(platform);
  const isPendingLimit = orderType === 'LIMIT'
    && orderPrice > 0
    && canTrackPending
    && !(filledQty > 0);

  if (track !== false) {
    trackTrade({
      symbol,
      market,
      platform,
      side,
      entry,
      status: isPendingLimit ? 'PENDING' : 'OPEN',
      orderType,
      pendingPrice: isPendingLimit && price ? +price : undefined,
      pendingStatus: isPendingLimit ? (order?.status || 'NEW') : undefined,
      tp1: takeProfit ? +takeProfit : undefined,
      tp2: takeProfit2 ? +takeProfit2 : (takeProfit ? +takeProfit * 1.01 : undefined),
      sl: stopLoss ? +stopLoss : undefined,
      qty,
      leverage: market === 'FUTURES' ? lev : 1,
      marginType: market === 'FUTURES' ? margin : undefined,
      forexLots: isForexPlat ? +(lots || 0.01) : undefined,
      moneyMgmt: !!plan,
      riskUsd: plan ? plan.riskUsd : null,
      orderId: order.orderId,
      at: new Date().toISOString(),
      auto: false,
      autoClose: true,
      paper: isPaper,
      tp1Pct: tp1Pct != null ? +tp1Pct : 50,
      tp2Pct: tp2Pct != null ? +tp2Pct : 100,
      trailingStop: trailingStop != null ? !!trailingStop : true,
      trailPct: trailPct != null ? +trailPct : autoTradeConfig.trailPct,
      reasons: [fromSignal ? 'Signal trade' : 'Manual entry'],
      fromSignal: !!fromSignal,
      signalType: fromSignal ? (signalType || side) : undefined,
      signalScore: fromSignal ? signalScore : undefined,
      signalEntry: fromSignal ? signalEntry : undefined,
      signalGrade: fromSignal
        ? (['CAUTION', 'STRONG', 'HIGHER STRONG'].includes(signalGrade) ? signalGrade : 'NONE')
        : undefined,
      trailArmPct: trailArmPct != null ? +trailArmPct : autoTradeConfig.trailArmPct,
      bbLower: bbLower != null ? +bbLower : null,
      bbMid: bbMid != null ? +bbMid : null,
      bbUpper: bbUpper != null ? +bbUpper : null,
      bandExtended: false,
      // Martingale ladder (opt-in, manual trades too): the monitor loop adds
      // rungs on an adverse move + a fresh same-side signal for this pair.
      martEnabled: !!martingale,
      martLevel: 0,
      martBaseQuote: plan ? plan.quote : (quoteAmt ? +quoteAmt : undefined),
      martStepPct: martStepPct != null ? +martStepPct : autoTradeConfig.martStepPct,
      martMult: martMult != null ? +martMult : autoTradeConfig.martMult,
      martMaxAdds: martMaxAdds != null ? +martMaxAdds : autoTradeConfig.martMaxAdds,
      martRiskCapPct: martRiskCapPct != null ? +martRiskCapPct : autoTradeConfig.martRiskCapPct
    });
  }
  ownerStore.logActivity(userData(), {
    type: isPaper ? 'PAPER_TRADE' : 'LIVE_TRADE',
    detail: `${side} ${symbol} ${market} qty ${qty}${market === 'FUTURES' ? ` x${lev} ${margin}` : ''}`
  });
  notifyI18n('n_manual', 'n_manual_body', { side, symbol, qty }, true);
  return { order, paper: isPaper, qty, entry };
});

ipcMain.handle('trade:account', async (_e, market, platformId) => {
  const id = platformId || 'BINANCE';
  const creds = getRawKeys(id);
  if (id === 'FOREX_DEMO') return { ok: true, note: 'Forex Demo — no account API' };
  if (!creds || !exchanges.hasRequiredCreds(id, creds)) {
    throw new Error(`API keys missing for ${id}`);
  }
  const tested = await exchanges.testKeys(id, creds);
  if (id === 'BINANCE') {
    if (market === 'FUTURES') {
      const bal = await binance.getFuturesBalance();
      return { test: tested, futuresBalance: bal };
    }
    const acct = await binance.getSpotAccount();
    return { test: tested, spotAccount: acct };
  }
  return tested;
});

ipcMain.handle('trades:list', () => openTrades);
ipcMain.handle('trades:clear-broken', () => clearBrokenTrades());
ipcMain.handle('trades:add-paper', (_e, trade) => {
  trackTrade({ ...trade, auto: false, paper: true, autoClose: true });
  return openTrades;
});

/** Full or partial close by trade id or symbol */
ipcMain.handle('trades:close', async (_e, { id, symbol, pct = 100 }) => {
  const t = openTrades.find((x) =>
    x.status === 'OPEN' && ((id && x.id === id) || (!id && x.symbol === symbol))
  );
  if (!t) return { ok: false, error: 'Trade not found' };
  const price = t.lastPrice || t.entry || (await getLastPrice(t));
  return closeTradePartial(t, price, 'MANUAL', pct);
});

/** Update TP/SL / autoClose while trade is open */
ipcMain.handle('trades:update', (_e, { id, symbol, tp1, tp2, sl, autoClose, tp1Pct, tp2Pct, cancelAuto, trailingStop, trailPct, tps }) => {
  const t = openTrades.find((x) =>
    x.status === 'OPEN' && ((id && x.id === id) || (!id && x.symbol === symbol))
  );
  if (!t) return { ok: false, error: 'Trade not found' };
  if (Array.isArray(tps)) {
    const clean = tps
      .filter((x) => x && +x.price > 0)
      .map((x) => ({ price: +x.price, pct: Math.max(0, Math.min(100, +x.pct || 0)), hit: false }));
    t.tps = clean;
    t.tp1 = clean[0] ? clean[0].price : null;
    t.tp2 = clean[1] ? clean[1].price : null;
    t.tp1Pct = clean[0] ? clean[0].pct : 0;
    t.tp2Pct = clean[1] ? clean[1].pct : 0;
    t.hitTp1 = false;
    t.hitTp2 = false;
  }
  if (tp1 != null && tp1 !== '') t.tp1 = +tp1;
  if (tp2 != null && tp2 !== '') t.tp2 = +tp2;
  if (sl != null && sl !== '') t.sl = +sl;
  if (tp1Pct != null) t.tp1Pct = +tp1Pct;
  if (tp2Pct != null) t.tp2Pct = +tp2Pct;
  if (autoClose != null) t.autoClose = !!autoClose;
  if (trailingStop != null) t.trailingStop = !!trailingStop;
  if (trailPct != null && trailPct !== '') t.trailPct = +trailPct;
  if (cancelAuto) {
    t.auto = false;
    t.autoClose = false;
  }
  // allow re-arm TP hits if user moved levels further
  if (tp1 != null) t.hitTp1 = false;
  if (tp2 != null) t.hitTp2 = false;
  persistTrades();
  mainWindow?.webContents.send('trades:update', openTrades);
  return { ok: true, trade: t };
});

ipcMain.handle('trades:cancel-auto', (_e, { id, symbol }) => {
  const t = openTrades.find((x) =>
    x.status === 'OPEN' && ((id && x.id === id) || (!id && x.symbol === symbol))
  );
  if (!t) return { ok: false };
  t.auto = false;
  t.autoClose = false;
  persistTrades();
  notifyI18n('n_auto_cancel', 'n_auto_cancel_body', { symbol: t.symbol }, true);
  mainWindow?.webContents.send('trades:update', openTrades);
  return { ok: true, trade: t };
});

/**
 * Pending (unfilled) LIMIT orders, per platform.
 * `exchange` = live truth from the exchange order book; `local` = the app's own
 * PENDING records. Platforms with no order-lookup API return supported:false and
 * an empty exchange list (the app list is still shown).
 */
ipcMain.handle('orders:pending', async (_e, { platform = 'BINANCE', market } = {}) => {
  const id = platform || 'BINANCE';
  const supported = exchanges.supportsOrderLookup(id);
  const out = {
    platform: id,
    supported,
    exchange: [],
    local: openTrades.filter((t) => t.status === 'PENDING' && (t.platform || 'BINANCE') === id),
    error: null
  };
  if (!supported) return out;
  const creds = getRawKeys(id);
  if (!creds || !exchanges.hasRequiredCreds(id, creds)) {
    out.error = `API keys missing for ${id}`;
    return out;
  }
  try {
    out.exchange = (await exchanges.listOpenOrders(id, creds, { market })) || [];
  } catch (e) {
    out.error = e.message || String(e);
  }
  return out;
});

/** Cancel a pending order on the exchange and drop its local PENDING record. */
ipcMain.handle('orders:cancel', async (_e, { id, platform = 'BINANCE', market, symbol, orderId } = {}) => {
  const plat = platform || 'BINANCE';
  const creds = getRawKeys(plat);
  if (!creds || !exchanges.hasRequiredCreds(plat, creds)) throw new Error(`API keys missing for ${plat}`);
  const ord = await exchanges.cancelPending(plat, creds, { market, symbol, orderId });
  openTrades = openTrades.filter((t) =>
    !(t.platform === plat && t.orderId && String(t.orderId) === String(orderId))
  );
  persistTrades();
  mainWindow?.webContents.send('trades:update', openTrades);
  notifyI18n('n_pending_cancelled', null, { _body: `${symbol} · ${market || 'SPOT'}: order cancelled` }, true, 'warn');
  return { ok: true, order: ord, open: openTrades };
});

/**
 * Clear a trade from the app list. By default it first checks the exchange:
 * if the position is still open there, it refuses unless `force` is set — so a
 * live trade can never be wiped by accident.
 */
ipcMain.handle('trades:forget', async (_e, { id, symbol, force } = {}) => {
  const t = openTrades.find((x) => (id && x.id === id) || (!id && x.symbol === symbol));
  if (!t) return { ok: false, error: 'Trade not found' };
  const plat = t.platform || 'BINANCE';
  if (!force && exchanges.supportsOrderLookup(plat)) {
    const creds = getRawKeys(plat);
    if (creds && exchanges.hasRequiredCreds(plat, creds)) {
      try {
        const chk = await exchanges.positionStillOpen(plat, creds, { market: t.market, symbol: t.symbol });
        if (chk.known && chk.exists) {
          return {
            ok: false,
            stillOpen: true,
            error: `${plat} still shows ${t.symbol} open — close it on the exchange first, or use Force clear.`
          };
        }
      } catch (e) {
        return { ok: false, error: `Cannot verify with ${plat}: ${e.message || e} — retry or Force clear.` };
      }
    }
  }
  forgetTradeLocal(t);
  return { ok: true, open: openTrades };
});

/**
 * Reconcile every trade against the exchange:
 *  - PENDING  → promote to OPEN when filled, drop when cancelled/expired
 *  - OPEN / SL_ALERT → drop when the exchange no longer shows the position
 * Platforms without an order-lookup API are left untouched (reported as skipped).
 */
ipcMain.handle('trades:sync', async (_e, { platform } = {}) => {
  const res = { checked: 0, cleared: 0, promoted: 0, kept: 0, skipped: 0, errors: [] };
  for (const t of [...openTrades]) {
    const plat = platform || t.platform || 'BINANCE';
    if (platform && (t.platform || 'BINANCE') !== platform) continue;
    if (!isActiveTrade(t)) continue;
    if (!exchanges.supportsOrderLookup(plat)) { res.skipped += 1; continue; }
    const creds = getRawKeys(plat);
    if (!creds || !exchanges.hasRequiredCreds(plat, creds)) { res.skipped += 1; continue; }
    res.checked += 1;
    if (t.status === 'PENDING') {
      const before = t.status;
      await reconcilePendingTrade(t);
      if (before === 'PENDING' && t.status === 'OPEN') res.promoted += 1;
      else if (!openTrades.includes(t)) res.cleared += 1;
      continue;
    }
    try {
      const chk = await exchanges.positionStillOpen(plat, creds, { market: t.market, symbol: t.symbol });
      if (!chk.known) { res.skipped += 1; continue; }
      if (chk.exists) { res.kept += 1; continue; }
      forgetTradeLocal(t);
      res.cleared += 1;
    } catch (e) {
      res.errors.push(`${t.symbol}: ${e.message || e}`);
    }
  }
  persistTrades();
  mainWindow?.webContents.send('trades:update', openTrades);
  return res;
});

