/* Saves a chart screenshot (PNG data URL built in the renderer) to a file the user picks. */
ipcMain.handle('chart:saveImage', async (_e, payload) => {
  const dataUrl = String(payload?.dataUrl || '');
  const m = /^data:image\/png;base64,(.+)$/.exec(dataUrl);
  if (!m) return { ok: false, message: 'Invalid image data' };
  const suggested = String(payload?.name || 'cpe-chart.png').replace(/[^\w.\-]+/g, '_');
  const opts = {
    title: 'Save chart screenshot',
    defaultPath: path.join(app.getPath('pictures') || userData(), suggested),
    filters: [{ name: 'PNG Image', extensions: ['png'] }]
  };
  const res = mainWindow && !mainWindow.isDestroyed()
    ? await dialog.showSaveDialog(mainWindow, opts)
    : await dialog.showSaveDialog(opts);
  if (res.canceled || !res.filePath) return { ok: false, canceled: true };
  try {
    fs.writeFileSync(res.filePath, Buffer.from(m[1], 'base64'));
    return { ok: true, path: res.filePath };
  } catch (err) {
    return { ok: false, message: err.message };
  }
});
